/* DAWAH X — ahmad, অধ্যায় 48 · খণ্ড 48 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][48]=[[9401,9401,"","আমি আপনার টাকা যারা আমার ভালবাসা হারিয়েছে তাদের কাছে কথা বলেছি, ঈশ্বরের কাছে প্রার্থনা করেছেন এবং যখন তাকে পাওয়া যাবে তখন তিনি তাদের কাছে পৌঁছে দেবেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ فَسَهَا فَلَمَّا سَلَّمَ سَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ ‏","","",""],[9402,9402,"","আমরা আমার ভাই, ঈশ্বরের রাজা কথা বলেছি, তিনি বলেন যে একটি ছেলে প্রার্থনা করছে যদি তিনি এটা চুরি করতে চান","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ فُلَانًا ‏ ‏يُصَلِّي بِاللَّيْلِ فَإِذَا أَصْبَحَ سَرَقَ قَالَ إِنَّهُ ‏ ‏سَيَنْهَاهُ مَا يَقُولُ ‏","","",""],[9403,9403,"","আমরা একে অপরের কথা বলেছি, কিন্তু আমরা একজন বংশধরের স্বপ্ন দেখেছি যে আমার বাবার মুক্তির জন্য ঘোড়ার পুত্র হিসেবে... তাকে জিজ্ঞাসা করুন","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَامِلًا ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏وَلُعَابُهُ يَسِيلُ عَلَيْهِ ‏","","",""],[9404,9404,"","আমরা একজন শিকারীর প্রতি আবেগ নিয়ে কথা বলেছি যে আমার বাবার দানে চালিত হয়েছে. আমি তোমাকে যা দেব যখন তুমি তাদের জিজ্ঞেস করবে তুমি চলে যাবে. তুমি পারবে আর আমরা তাকে এড়াতে কিছু একটা করব।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَاتَّبِعُوهُ مَا اسْتَطَعْتُمْ وَإِذَا نَهَيْتُكُمْ عَنْ أَمْرٍ فَاجْتَنِبُوهُ ‏","","",""],[9405,9405,"","আমরা দুই মাস ধরে কথা বলেছি আমার বাবা আর বাবার মধ্যে দেবতা হওয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَهُ سَكْتَةٌ فِي الصَّلَاةِ ‏","","",""],[9406,9406,"","ঈশ্বর আমাদের প্রভুর প্রতি প্রেম দেখিয়েছেন কিন্তু পুরুষদের জন্য তারা পুলিশের কাছে গাড়ি চালাচ্ছে ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَامِلٌ أَبُو الْعَلَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ قَوْمٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ ‏","","",""],[9407,9407,"","ঈশ্বরের সঙ্গে আপনার সম্পর্ক দৃঢ় করুন","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏كَامِلٌ أَبُو الْعَلَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَوَّذُوا بِاللَّهِ مِنْ رَأْسِ السَّبْعِينَ وَإِمَارَةِ الصِّبْيَانِ ‏","","",""],[9408,9408,"","আমরা আমার ছেলের বিয়ের ব্যাপারে দুই গ্রীষ্মের কথা বলেছি, আমি তাকে ভবিষ্যদ্বাণী করতে যাচ্ছি, ঈশ্বর তাকে একটা হাত দিতে হবে বলে সে সবসময় বলবে যে সে হয়তো তার পক্ষে সম্ভব তার যে ক্ষতি হয়েছে তা শোনো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏الطُّفَيْلُ ‏ ‏وَأَصْحَابُهُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏دَوْسًا ‏ ‏قَدْ اسْتَعْصَتْ قَالَ ‏ ‏اللَّهُمَّ اهْدِ ‏ ‏دَوْسًا ‏ ‏وَأْتِ بِهِمْ ‏","","",""],[9409,9409,"","ঈশ্বরের হাতে কথা বলেছি কিন্তু ঈশ্বরের কাছে আছে। আমার বাবা, ঈশ্বরের কাছে প্রার্থনা করেছেন, আর একজন পণ্ডিতের কাছে তার মুখ থেকে নিজেকে আত্মসমর্পণ করেছেন। আমি তাকে দান করিনি। হয় তার গতি বাড়িয়ে বা তার শক খেয়ে ফেল।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمٍ ‏ ‏يَنْصِبُ ‏ ‏وَجْهَهُ لِلَّهِ عَزَّ وَجَلَّ فِي مَسْأَلَةٍ إِلَّا أَعْطَاهَا إِيَّاهُ إِمَّا أَنْ يُعَجِّلَهَا لَهُ وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ ‏","","",""],[9410,9410,"","আমরা একে অপরের নাম কথা বলেছি যে ছেলে ছেলে হতে পারে। আমার বাবা এমন একটা উপহার যেটা ভাববাদীর ইচ্ছা তৈরি করেছে আর প্রার্থনা করতে ব্যর্থ হয়েছে যখন তিনি রাজা হয়েছেন। আমি বাইরে গিয়ে তাদের জিজ্ঞেস করছি আমি ঠিক হয়ে যাব কিনা।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْأَسْوَدِ بْنِ سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الصَّلَاةِ فَلَمَّا كَبَّرَ انْصَرَفَ ‏ ‏وَأَوْمَأَ ‏ ‏إِلَيْهِمْ أَيْ كَمَا أَنْتُمْ ثُمَّ خَرَجَ فَاغْتَسَلَ ثُمَّ جَاءَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى بِهِمْ فَلَمَّا صَلَّى قَالَ ‏ ‏إِنِّي كُنْتُ ‏ ‏جُنُبًا ‏ ‏فَنَسِيتُ أَنْ أَغْتَسِلَ ‏","","",""],[9411,9411,"","সেই যমজ ভাই বলেছিলেন যে, আমি বাবার কাছে সংবাদ নিয়ে গিয়েছিলাম এবং তিনি বলেছিলেন যে তার একটা মই আছে । উত্তম ভালুক হওয়ার অর্থ কী ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَنْعَتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ ‏ ‏شَبْحَ الذِّرَاعَيْنِ أَهْدَبَ ‏ ‏أَشْفَارِ ‏ ‏الْعَيْنَيْنِ بَعِيدَ مَا بَيْنَ ‏ ‏الْمَنْكِبَيْنِ ‏ ‏يُقْبِلُ إِذَا أَقْبَلَ جَمِيعًا ‏ ‏وَيُدْبِرُ ‏ ‏إِذَا ‏ ‏أَدْبَرَ ‏ ‏جَمِيعًا ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فِي حَدِيثِهِ بِأَبِي وَأُمِّي لَمْ يَكُنْ ‏ ‏فَاحِشًا ‏ ‏وَلَا ‏ ‏مُتَفَحِّشًا ‏ ‏وَلَا ‏ ‏سَخَّابًا ‏ ‏بِالْأَسْوَاقِ ‏","","",""],[9412,9412,"","আমার ছেলের কাছে শপথ করে বলতেই হয় যে, আমার বাবা একজন উৎপীড়ক আর তিনি বলবেন যে, তিনি পবিত্র মায়ের কাছে প্রার্থনা করেছেন যে তিনি সঠিক ব্যক্তি পৃথিবীর সেরা পাঠক।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏أُمِّ الْقُرْآنِ ‏ ‏هِيَ ‏ ‏أُمُّ الْقُرْآنِ ‏ ‏وَهِيَ ‏ ‏السَّبْعُ الْمَثَانِي ‏ ‏وَهِيَ ‏ ‏الْقُرْآنُ الْعَظِيمُ ‏","","",""],[9413,9413,"","আমার বাবার সাথে কথা বলেছি আমার ভাইকে বলার জন্য। তার বাবার কথা শুনে ভালো মেয়ে বলে যে সে বলেছিল আমি যদি অসুস্থ হয়ে যেতে চাই তাহলে ঈশ্বর চলে যাবে। সে যা করেছে তা বলার জন্য, ঈশ্বর ঈশ্বরের কাছে সঠিক পথে যেতে পারেন, সে তোমার আশার চেয়ে বেশি কিছু তার টাকা দিতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَمْرَانِ لَأَحْبَبْتُ أَنْ أَكُونَ مَمْلُوكًا وَذَلِكَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا خَلَقَ اللَّهُ عَبْدًا يُؤَدِّي حَقَّ اللَّهِ وَحَقَّ سَيِّدِهِ إِلَّا وَفَّاهُ اللَّهُ أَجْرَهُ مَرَّتَيْنِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏إِنَّ الْمَمْلُوكَ لَا يَسْتَطِيعُ أَنْ يَصْنَعَ فِي مَالِهِ شَيْئًا ‏","","",""],[9414,9414,"","আমরা আমার বাবা তার বাবাকে জয় করার চেষ্টা করেছিলেন বলে আমরা কথা বলেছি। তিনি কোরানের মা এবং লেখকদের মা ও অন্য দুই সন্তানের মা আপনার অনুপ্রেরণার জন্য আপনার অনুপ্রেরণা হিসেবে নিজেকে সমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَمْدُ لِلَّهِ ‏ ‏أُمُّ الْقُرْآنِ ‏ ‏وَأُمُّ الْكِتَابِ ‏ ‏وَالسَّبْعُ الْمَثَانِي ‏","","",""],[9415,9415,"","আমি আমার বাবার কথা বলেছিলাম আমার বাবা একজন দেবতা, তিনি শান্তি বজায় রাখবেন আর তিনি সাহসী হওয়ার ক্ষমতায় যোগ দেবেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ سَتَحْرِصُونَ عَلَى الْإِمَارَةِ وَسَتَصِيرُ نَدَامَةً وَحَسْرَةً يَوْمَ الْقِيَامَةِ فَبِئْسَتْ الْمُرْضِعَةُ ‏ ‏وَنِعْمَتْ الْفَاطِمَةُ ‏","","",""],[9416,9416,"","আমরা আমার বাবা একজন পলাতক ব্যক্তি হওয়া সম্পর্কে কথা বলেছি যে তার মৃত্যু আর তার কল্পনার কথা বলেছে। আমার বলা উচিত, তুমি আমার জীবনের সবচেয়ে খারাপ মানুষ। তিনি আমাকে বলেছিলেন যে, সুখী ও প্রেমময় তিনি হলেন সর্বোত্তম ব্যক্তি । সিঁড়ি তাদের আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏اخْتَصَمَ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِمَا وَسَلَّمَ فَخَصَمَ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَقَالَ ‏ ‏مُوسَى ‏ ‏أَنْتَ ‏ ‏آدَمُ ‏ ‏الَّذِي أَشْقَيْتَ النَّاسَ وَأَخْرَجْتَهُمْ مِنْ الْجَنَّةِ فَقَالَ ‏ ‏آدَمُ ‏ ‏أَنْتَ ‏ ‏مُوسَى ‏ ‏الَّذِي ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِرِسَالَاتِهِ وَبِكَلَامِهِ وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ أَلَيْسَ تَجِدُ فِيهَا أَنْ قَدْ قَدَّرَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي قَالَ بَلَى قَالَ ‏ ‏عَمْرُو بْنُ سَعِيدٍ ‏ ‏وَابْنُ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيُّ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏يَكْفِينِي أَوَّلُ الْحَدِيثِ فَخَصَمَ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[9417,9417,"","আমরা আমার প্রিয় বাবা আমাদের সম্পর্কে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আত্মসমর্পণ করেছেন, আমার প্রভু হয়তো আপনার আত্মা কিনে নিয়েছেন। আমি বলতে চাচ্ছি, আপনি ঈশ্বরের দোহাই, আমি আমার প্রিয় পিতা তোমার পাছা উড়িয়ে দাও।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ يَا ‏ ‏صَفِيَّةُ عَمَّةَ رَسُولِ اللَّهِ ‏ ‏وَيَا ‏ ‏فَاطِمَةُ بِنْتَ رَسُولِ اللَّهِ ‏ ‏اشْتَرِيَا أَنْفُسَكُمَا مِنْ اللَّهِ لَا ‏ ‏أُغْنِي عَنْكُمَا مِنْ اللَّهِ شَيْئًا سَلَانِي مِنْ مَالِي مَا شِئْتُمَا ‏","","",""],[9418,9418,"","আমি যেন এটাকে এভাবে খাই ও তার টাকা খাই ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَيَأْتِيَنَّ عَلَى أَحَدِكُمْ يَوْمٌ لَأَنْ يَرَانِي ثُمَّ لَأَنْ يَرَانِي أَحَبُّ إِلَيْهِ مِنْ أَنْ يَكُونَ لَهُ مِثْلُ أَهْلِهِ وَمَالِهِ ‏","","",""],[9419,9419,"","ঈশ্বর তাকে আদেশ দিয়েছেন যেন আপনি তাঁকে ও তার সামন্ততা উপভোগ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْتَقِيمُ لَكَ الْمَرْأَةُ عَلَى خَلِيقَةٍ وَاحِدَةٍ إِنَّمَا هِيَ كَالضِّلَعِ إِنْ تُقِمْهَا تَكْسِرْهَا وَإِنْ تَتْرُكْهَا تَسْتَمْتِعْ بِهَا وَفِيهَا عِوَجٌ ‏","","",""],[9420,9420,"","আমরা বাবাকে সাহায্য করে অনেক খুশি হয়েছি, কারণ আমরা ঈশ্বরের কাছে প্রার্থনা করেছি, তিনি তাঁর কাছে প্রার্থনা করেছেন এবং সেই নিষ্ঠুর মানুষের মৃত্যুর পর ছায়াকে আত্মসমর্পণ করবেন। ঈশ্বর আপনি এটা কিভাবে ছেড়ে দিবেন সেটা দেখবেন না। ঈশ্বর আমার হাত থেকে আমার উত্তরাধীকে দেখেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ وَفِي مُؤَخَّرِ الصُّفُوفِ رَجُلٌ فَأَسَاءَ الصَّلَاةَ فَلَمَّا سَلَّمَ نَادَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ أَلَا تَتَّقِي اللَّهَ أَلَا ‏ ‏تَرَى كَيْفَ تُصَلِّي إِنَّكُمْ تَرَوْنَ أَنَّهُ ‏ ‏يَخْفَى عَلَيَّ شَيْءٌ مِمَّا تَصْنَعُونَ وَاللَّهِ ‏ ‏إِنِّي لَأَرَى مِنْ خَلْفِي كَمَا أَرَى مِنْ بَيْنِ يَدَيَّ ‏","","",""],[9421,9421,"","আমি আমার বাবাকে আগে যে - ট্রিগারে করে বলেছিলাম, তা নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ صَالِحُ نِسَاءِ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ ‏","","",""],[9422,9422,"","আমরা আমার বাবাকে যাজক হওয়ার বিষয়ে বলেছিলাম । সে-ই ব ্ যতীত যে সত ্ যনিষ ্ ঠ হবে , আর সে হবে ক ্ ষতিগ ্ রস ্ ত । যে লোক হবে এই কোরআন , যার ইচ ্ ছা , সে ব ্ যতীত হবে , যে , সে হবে বিজয়ী হবে । রাজা.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمِسْكِينَ لَيْسَ بِالَّذِي تَرُدُّهُ التَّمْرَةُ وَلَكِنَّ الْمِسْكِينَ الَّذِي لَا يَسْأَلُ النَّاسَ وَلَا يُفْطَنُ لَهُ فَيُعْطَى ‏","","",""],[9423,9423,"","আমরা বাবার জেদের জন্য বাপ্তাইজিত হওয়ার ব্যাপারে কথা বলেছি, আমি আমার বাবা একটা ঘোড়ার কথা বলছি না যে বলল যে ঈশ্বর এটা দিয়েছেন.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَمُحَمَّدٌ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَبَا صَالِحٍ السَّمَّانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[9424,9424,"","আমরা একটা নির্দিষ্ট ছেলের বিয়ের ব্যাপারে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তার কাজের জন্য শহর গেটের কাছে আত্মসমর্পণ করেছেন। ( আদিপুস্তক ১: ২৭) সেই পিতা হলেন সতী, ঈশ্বর আপনাকে থাকতে বলবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ أَهْلِ عَمَلٍ بَابٌ مِنْ أَبْوَابِ الْجَنَّةِ يُدْعَوْنَ بِذَلِكَ الْعَمَلِ وَلِأَهْلِ الصِّيَامِ بَابٌ يُدْعَوْنَ مِنْهُ يُقَالُ لَهُ ‏ ‏الرَّيَّانُ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ أَحَدٌ يُدْعَى مِنْ تِلْكَ الْأَبْوَابِ كُلِّهَا قَالَ نَعَمْ وَأَنَا أَرْجُو أَنْ تَكُونَ مِنْهُمْ يَا ‏ ‏أَبَا بَكْرٍ ‏","","",""],[9425,9425,"","আমি আমার বাবাকে আগে যে - ট্রিগারে দেখেছিলাম, সেই সম্বন্ধে বলেছিলাম । জিতে গেল, আর তার একটা শয়তান আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ نَبِيٌّ مِنْ الْأَنْبِيَاءِ تَحْتَ شَجَرَةٍ ‏ ‏فَلَدَغَتْهُ نَمْلَةٌ فَأَمَرَ ‏ ‏بِجَهَازِهِ ‏ ‏فَأُخْرِجَ مِنْ تَحْتِهَا ثُمَّ أَمَرَ بِهَا فَأُحْرِقَتْ بِالنَّارِ فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ فَهَلَّا نَمْلَةً وَاحِدَةً ‏","","",""],[9426,9426,"","আমরা ঈশ্বরের পুত্রকে একটা গোলামের সাথে মারতে বলেছিলাম, সে যদি জিততে না পারে, আমি নিশ্চিত নই সে একটা কুত্তার বাচ্চা হবে। যে আমাকে বলতে হবে যে আমার বাবা হতে হবে সেই হতে হবে যে তার নিজের থাকা উচিৎ। আমি না থাকলে তোমাকে ছেড়ে দেব না। তাকে ছেড়ে দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْمُغِيرَةِ بْنِ مُعَيْقِيبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمَانَ بْنِ عَبْدٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏لَمْ يُضْبَطْ إِسْنَادُهُ إِنَّمَا هُوَ ‏ ‏سُلَيْمَانُ بْنُ عَمْرِو بْنِ عَبْدٍ الْعُتْوَارِيُّ ‏ ‏وَهُوَ صَاحِبُ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَبُو الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَعَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَتَّخِذُ عِنْدَكَ ‏ ‏عَهْدًا ‏ ‏لَنْ تُخْلِفَنِيهِ فَإِنَّمَا أَنَا بَشَرٌ فَأَيُّ الْمُؤْمِنِينَ آذَيْتُهُ أَوْ شَتَمْتُهُ أَوْ لَعَنْتُهُ أَوْ جَلَدْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَصَلَاةً وَقُرْبَةً تُقَرِّبُهُ بِهَا إِلَيْكَ يَوْمَ الْقِيَامَةِ ‏","","",""],[9427,9427,"","আমরা বাবার স্বপ্নের কথা বলেছিলাম একটা স্বপ্নের স্বপ্ন ভেঙ্গে গেছে, সে একটা ব্রেসলেটে খুঁজে পেয়েছে যেটা সে পেয়েছিলো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَقُلْتُ سَجَدْتَ فِي سُورَةٍ مَا يُسْجَدُ فِيهَا قَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا ‏","","",""],[9428,9428,"","আমরা আমার বাবা কুমারী হওয়া সম্পর্কে কথা বলেছি যে আমাদের ঈশ্বর সম্পর্কে বলেছে, সে পাঠকদের ছেড়ে দেবে এবং ভুল মানুষকে ভুল লোককে হত্যা করবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ الْقَارِئُ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقَالَ مَنْ خَلْفَهُ آمِينَ فَوَافَقَ ذَلِكَ قَوْلَ أَهْلِ السَّمَاءِ آمِينَ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9429,9429,"","আমরা আমার বাবা একজন সাহসী ব্যক্তি, যে ঈশ্বরকে বলতে চায়, সে যা করেছে তা ছেড়ে দেবে এবং সে যা করেছে তা করবে যা তাকে গান গাইতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَذِنَ اللَّهُ عَزَّ وَجَلَّ لِشَيْءٍ كَإِذْنِهِ لِنَبِيٍّ ‏ ‏يَتَغَنَّى ‏ ‏بِالْقُرْآنِ يَجْهَرُ بِهِ ‏","","",""],[9430,9430,"","আমরা আমার বাবার কথা বলেছিলাম একজন কুমারীর সাথে যে কিনা ভিতরে যাবে সে তার কথা শুনবে যে হয়ত তাকে হত্যা করবে যে কিনা বলতে পারে যে ঈশ্বর একজন যাজকের মৃত্যুর আগে মারা গেছে আমার মৃত্যু.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ فَسَمِعَ قِرَاءَةَ رَجُلٍ فَقَالَ مَنْ هَذَا قِيلَ ‏ ‏عَبْدُ اللَّهِ بْنُ قَيْسٍ ‏ ‏فَقَالَ ‏ ‏لَقَدْ أُوتِيَ هَذَا مِنْ مَزَامِيرِ آلِ ‏ ‏دَاوُدَ ‏","","",""],[9431,9431,"","তিনি বলেন যে, আমি তার সমবেদনার জন্য ছেড়ে দেব এবং তার সমস্ত দিন শাস্তি পাব ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَسْتَغْفِرُ اللَّهَ عَزَّ وَجَلَّ وَأَتُوبُ إِلَيْهِ كُلَّ يَوْمٍ مِائَةَ مَرَّةٍ ‏","","",""],[9432,9432,"","আর তাকে ফোন করে তিনি ঈশ্বরের সাথে কথা বলার জন্য বলেন এবং সাম্প্রতিক সময়ের একটা সময়ে আত্মসমর্পণ করতে বলেন। আপনি তার টাকা নিয়ে ঈর্ষান্বিত। কখনোই স্বাধীন হতে পারবে না।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةُ ‏ ‏مَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا ‏ ‏حَدَثًا ‏ ‏أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏ ‏أَوْ ‏ ‏تَوَلَّى ‏ ‏غَيْرَ ‏ ‏مَوْلَاهُ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏","","",""],[9433,9433,"","আর তিনি আমার শান্তির জন্য এসে বলেন, \"ঈশ্বর তাঁর জন্য এসেছেন।\" আমি আদেশ করছি। তারপর তাঁর মৃত্যুর পর, ঈশ্বর এটা করতে চান। তিনি যখন তার চামড়াকে স্পর্শ করেছিলেন, তখন তিনি বলেছিলেন যে, তিনি পাথর স্পর্শ করার সময় তিনি তার চামড়া স্পর্শ করেছিলেন । সে তাকে ছেড়ে চলে গেছে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ جَاءَ ‏ ‏مَاعِزُ بْنُ مَالِكٍ الْأَسْلَمِيُّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ فَأَعْرَضَ عَنْهُ ثُمَّ جَاءَ مِنْ ‏ ‏شِقِّهِ ‏ ‏الْأَيْمَنِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ فَأَعْرَضَ عَنْهُ ثُمَّ جَاءَهُ مِنْ ‏ ‏شِقِّهِ ‏ ‏الْأَيْسَرِ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي قَدْ زَنَيْتُ فَقَالَ لَهُ ذَلِكَ أَرْبَعَ مَرَّاتٍ فَقَالَ انْطَلِقُوا بِهِ فَارْجُمُوهُ وَقَالَ فَانْطَلَقُوا بِهِ فَلَمَّا مَسَّتْهُ الْحِجَارَةُ ‏ ‏أَدْبَرَ ‏ ‏وَاشْتَدَّ فَاسْتَقْبَلَهُ ‏ ‏رَجُلٌ ‏ ‏فِي يَدِهِ لَحْيُ جَمَلٍ فَضَرَبَهُ بِهِ فَذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرَارُهُ حِينَ مَسَّتْهُ الْحِجَارَةُ قَالَ فَهَلَّا تَرَكْتُمُوهُ ‏","","",""],[9434,9434,"","আর সমর্থকরা দেরি করে তাঁর কাছে প্রার্থনা করবে ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الدِّينُ ظَاهِرًا مَا ‏ ‏عَجَّلَ ‏ ‏النَّاسُ الْفِطْرَ إِنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏يُؤَخِّرُونَ ‏","","",""],[9435,9435,"","( গীতসংহিতা ৩৭: ১১) এমনকি ঈশ্বরও জয়ী হয়েছেন এবং তাঁর ভুলগুলোকে তিনি ভুলে যাবেন না ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الْبَلَاءُ بِالْمُؤْمِنِ أَوْ الْمُؤْمِنَةِ فِي جَسَدِهِ وَمَالِهِ وَوَلَدِهِ حَتَّى يَلْقَى اللَّهَ عَزَّ وَجَلَّ وَمَا عَلَيْهِ مِنْ خَطِيئَةٍ ‏","","",""],[9436,9436,"","আর তাকে ফোন করে তিনি ঈশ্বরের কাছে তার শান্তির জন্য প্রার্থনা করেছিলেন এবং আমার অন্তর থেকে আত্মসমর্পণ করেছিলেন ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْبَرِي هَذَا عَلَى ‏ ‏تُرْعَةٍ ‏ ‏مِنْ ‏ ‏تُرَعِ ‏ ‏الْجَنَّةِ ‏","","",""],[9437,9437,"","আর তাকে কল করে তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তাঁর ইচ্ছার জন্য তিনি তাঁর জীবন দান করবেন এবং আমি তার জীবন চাই । আর দুনিয়ার মালিক.","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِفَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏خَيْرٌ مِنْ الْحَيَّيْنِ الْحَلِيفَيْنِ ‏ ‏أَسَدٍ ‏ ‏وَغَطَفَانَ ‏ ‏وَهَوَازِنَ ‏ ‏وَتَمِيمٍ ‏ ‏فَإِنَّهُمْ أَهْلُ الْخَيْلِ ‏ ‏وَالْوَبَرِ ‏","","",""],[9438,9438,"","আর তিনি ঈশ্বরের ইচ্ছার জন্য প্রার্থনা করতে বলেছেন, তাকে তার টাকা ছেড়ে চলে যাওয়া পর্যন্ত আত্মসমর্পণ করতে হবে, তাই তিনি এটা ভাল কাজ করতেন।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ وَمَنْ تَرَكَ ‏ ‏ضِيَاعًا ‏ ‏فَإِلَيَّ ‏","","",""],[9439,9439,"","আর সে বলেছে, ঈশ্বরের কাছে প্রার্থনা করে, সে আমাকে ছেড়ে দেবে যেন সে আমার সাথে অন্ত্যেষ্টিক্রিয়ার জন্য ঋণী থাকে, সে বলে দেবে তার কাছে এটা আছে আর তার কাছে আছে। সে তোমার কাছে আত্মসমর্পণ করবে আর তোমার দশ আদর্শের কাছে.","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً مَنْ يَتَمَنَّى عَلَى اللَّهِ عَزَّ وَجَلَّ فَيُقَالُ لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ إِلَّا أَنَّهُ يُلَقَّنُ فَيُقَالُ لَهُ كَذَا وَكَذَا فَيُقَالُ لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيُقَالُ لَكَ ذَلِكَ وَعَشَرَةُ أَمْثَالِهِ ‏","","",""],[9440,9440,"","আর তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন যেন তিনি আগুন নেভাতে এবং আগুন না পারেন । তুমি আমার নিজের.","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَّتْ ‏ ‏النَّارُ وَالْجَنَّةُ فَقَالَتْ النَّارُ يَدْخُلُنِي الْجَبَّارُونَ وَالْمُتَكَبِّرُونَ وَقَالَتْ الْجَنَّةُ يَدْخُلُنِي الضُّعَفَاءُ وَالْمَسَاكِينُ فَقَالَ اللَّهُ عَزَّ وَجَلَّ لِلنَّارِ ‏ ‏أَنْتِ عَذَابِي أَنْتَقِمُ بِكِ مِمَّنْ شِئْتُ وَقَالَ لِلْجَنَّةِ أَنْتِ رَحْمَتِي أَرْحَمُ بِكِ مَنْ شِئْتُ ‏","","",""],[9441,9441,"","আর সে বলল যে ভগবানের কাছে প্রার্থনা করুক, আর আমি যা চাই তা ফিরিয়ে দিতে চাই। আমি তাকে একভাবে চুমু দেই।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُحِبُّ أَنَّ لِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا يَمُرُّ عَلَيَّ ثَالِثَةٌ وَعِنْدِي مِنْهُ فَأَجِدُ مَنْ يَقْبَلُهُ مِنِّي إِلَّا أَنْ ‏ ‏أَرْصُدَهُ ‏ ‏فِي دَيْنٍ يَكُونُ عَلَيَّ ‏","","",""],[9442,9442,"","তিনি বলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং তিনি তার সমস্ত স্বপ্ন ছেড়ে না যেতে পর্যন্ত যেতে হবে না. এবং তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন তিনি তা করেছেন.","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ ثَلَاثُونَ كَذَّابًا رِجَالًا كُلُّهُمْ يَكْذِبُ عَلَى اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9443,9443,"","আর সে ঈশ্বরকে জিজ্ঞেস করলো যে তিনি তার শান্তির জন্য প্রার্থনা করেছেন আর তিনি তার আগের চেয়ে সূর্যকে অনুসরণ করেছেন। আর তারপর তারা তাদের সাথে যাওয়ার জন্য একটি শিয়াল গর্তে ভেতরে চলে যেত, বলে, \"ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর.\"","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَتَّبِعُنَّ سُنَنَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بَاعًا ‏ ‏بِبَاعٍ ‏ ‏وَذِرَاعًا بِذِرَاعٍ وَشِبْرًا بِشِبْرٍ حَتَّى لَوْ دَخَلُوا فِي جُحْرِ ضَبٍّ لَدَخَلْتُمْ مَعَهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏قَالَ فَمَنْ إِذًا ‏","","",""],[9444,9444,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন, আর আমাদের যদি ভাল কিছু করতে হতো তাহলে তিনি তা রক্ষা করতেন। তারপর আল্লাহ তাকে ক্ষমা করে দিলেন যেন তিনি ডুবে না যান। জিনিয়াসকে এটা ব্যাখ্যা করতে দেখিনি।","‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا أَنَا عَلَى بِئْرٍ أَسْقِي فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏ذَنُوبَيْنِ ‏ ‏وَفِيهِمَا ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ جَاءَ ‏ ‏عُمَرُ ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏فَنَزَعَ ‏ ‏حَتَّى اسْتَحَالَتْ فِي يَدِهِ ‏ ‏غَرْبًا ‏ ‏وَضَرَبَ النَّاسُ ‏ ‏بِعَطَنٍ ‏ ‏فَلَمْ أَرَ ‏ ‏عَبْقَرِيًّا ‏ ‏يَفْرِي ‏ ‏فَرْيَهُ ‏","","",""],[9445,9445,"","এটা শিকার আমাকে দোরগোড়ায় হুমকি দিচ্ছে, যাকে রাজা মূসা অপহরণ করেছে। আমাদের কথায় আমি প্রভু হতে চাই। তাকে ঈশ্বরের কাছে হস্তান্তর করা হয়েছে। সে তার কাছে প্রার্থনা করে ছবি আর নেকড়েদের কাছে আত্মসমর্পণ করে। তারপর সে আবার উড়ে গেল, তাই তারা হল আমার প্রভু। আমি যদি আমার কাছে নিশ্চিত হই, আমি যদি আমার প্রভু হই, তাহলে আমি তাকে ছেড়ে দেব। আমি যদি আমার জীবনের সব ছবি তুলে ধরি, তাহলে আমি যদি তাকে ছেড়ে দেব, তাহলে আমি যদি তাকে ছেড়ে দেব, তাহলে আমি তোমার কাছে ক্ষমা চাই, আর আমার কাছে আমার মনের কথা বলি, আমি জানি আমি আগে আমি ঈশ্বরকে ভুলে যেতাম আর কে বলল আমি একজন ভালো দাসী যে অনেক দিন আগে চলে যেতাম।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ قَالَ ‏ ‏يَهُودِيٌّ ‏ ‏بِسُوقِ ‏ ‏الْمَدِينَةِ ‏ ‏وَالَّذِي ‏ ‏اصْطَفَى ‏ ‏مُوسَى ‏ ‏عَلَى الْبَشَرِ قَالَ ‏ ‏فَلَطَمَهُ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ تَقُولُ هَذَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِينَا قَالَ فَأَتَى الْيَهُودِيُّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ ‏} ‏قَالَ فَأَكُونُ أَوَّلَ مَنْ يَرْفَعُ رَأْسَهُ فَإِذَا ‏ ‏مُوسَى ‏ ‏آخِذٌ بِقَائِمَةٍ مِنْ قَوَائِمِ الْعَرْشِ فَلَا أَدْرِي أَرَفَعَ رَأْسَهُ قَبْلِي أَمْ كَانَ مِمَّنْ ‏ ‏اسْتَثْنَى ‏ ‏اللَّهُ وَمَنْ قَالَ أَنِّي خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏فَقَدْ كَذَبَ ‏","","",""],[9446,9446,"","আর তাকে ফোন করে তিনি ঈশ্বরের কাছে প্রার্থনা করেন যে তিনি ঈশ্বরকে উদ্ধার করতে চান না বলে ঈশ্বর তাকে বাঁচাতে চান না। যদি তিনি আমাকে ঘৃণা করেন তিনি আমার বাবার সাথে দেখা করতে বলেন তিনি একজন বাবা। কুমারী, আমার বাবা একজন কুমারী, যদি তোমার দোষটা তোমার, সে খুঁজে পেত।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِذَا أَحَبَّ الْعَبْدُ لِقَائِي أَحْبَبْتُ لِقَاءَهُ وَإِذَا كَرِهَ الْعَبْدُ لِقَائِي كَرِهْتُ لِقَاءَهُ ‏ ‏قَالَ ‏ ‏فَقِيلَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏مَا مِنَّا مِنْ أَحَدٍ إِلَّا وَهُوَ يَكْرَهُ الْمَوْتَ وَيَفْظَعُ بِهِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنَّهُ إِذَا كَانَ ذَلِكَ كَشَفَ بِهِ ‏","","",""],[9447,9447,"","ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি শত বছর ধরে অমৎসিয়ার অনুপ্রেরণার শপথে প্রবেশ করবেন ।","‏ ‏وَبِالْإِسْنَادِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ فُقَرَاءُ الْمُؤْمِنِينَ الْجَنَّةَ قَبْلَ الْأَغْنِيَاءِ بِنِصْفِ يَوْمٍ خَمْسِ مِائَةِ سَنَةٍ ‏","","",""],[9448,9448,"","প্রভু, ঈশ্বর আদেশ দিয়েছেন, আমি ঈশ্বর এবং আমাকে দয়া করে করুন, বা তারা বিড়ালের মধ্যে প্রবেশ করে না।","‏ ‏وَبِالْإِسْنَادِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ خَلَقَ كَخَلْقِي فَلْيَخْلُقُوا بَعُوضَةً أَوْ لِيَخْلُقُوا ذَرَّةً ‏","","",""],[9449,9449,"","আমরা আমার বাবার মেয়রের ব্যাপারে কথা বলেছি, তুমি ঐ যৌন নার্সকে খুঁজে পাওনি, যে আমাকে আমার সৌজন্য বলে ডাকে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا لَمْ تَجِدُوا إِلَّا ‏ ‏مَرَابِضَ ‏ ‏الْغَنَمِ ‏ ‏وَمَعَاطِنَ ‏ ‏الْإِبِلِ فَصَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي ‏ ‏مَعَاطِنِ ‏ ‏الْإِبِلِ ‏","","",""],[9450,9450,"","আমরা বাবার প্রেমের বিষয়ে তার ভালোবাসা সম্বন্ধে জেনে খুশি হয়েছিলাম । আমি তাদের আদেশ করবো, বাবা শপথ করে বলে, আমি আবার বলতে চাই, যে আপনাকে তার টাকা বিক্রি করতে হবে নাকি তাদের তা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ فِي الْمَسْجِدِ خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ انْطَلِقُوا إِلَى ‏ ‏يَهُودَ ‏ ‏فَخَرَجْنَا مَعَهُ حَتَّى جِئْنَا ‏ ‏بَيْتَ الْمِدْرَاسِ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَادَاهُمْ يَا ‏ ‏مَعْشَرَ ‏ ‏الْيَهُودِ ‏ ‏أَسْلِمُوا تَسْلَمُوا فَقَالُوا قَدْ بَلَّغْتَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏قَالَ ذَاكَ أُرِيدُ ثُمَّ قَالَهَا الثَّالِثَةَ فَقَالَ اعْلَمُوا أَنَّ الْأَرْضَ لِلَّهِ وَرَسُولِهِ وَإِنِّي أُرِيدُ أَنْ ‏ ‏أُجْلِيَكُمْ ‏ ‏مِنْ هَذِهِ الْأَرْضِ فَمَنْ وَجَدَ مِنْكُمْ بِمَالِهِ شَيْئًا فَلْيَبِعْهُ وَإِلَّا فَاعْلَمُوا أَنَّ الْأَرْضَ لِلَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏","","",""],[9451,9451,"","আর তিনি আমার বাবার ব্যাপারে ফোন করেছেন, একজন ভালো মানুষ যে বলেছে, ঈশ্বরকে দেখার জন্য সে এত গর্বিত কেন? যে ই একমাত্র সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি, যিনি ছিলেন সেই ব্যক্তি । তিনিই সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি । তোমাকে কিছু বলতে ভয় পাচ্ছি, ঈশ্বর তোমাকে কিছু বলতে চান আমি বিশ্বাস করব, তোমার বাবা তাকে বলেছে যে তিনি ঈশ্বরের কাছে বলেছেন. আপনি বলেছিলেন যে, তারা এমন কিছু সম্বন্ধে বলে, যেগুলো আমি আপনাকে জানতে চাই, যেমন চলে যাও । তার কাছে এবং আমি যাকে খুশি তার কাছে আত্মসমর্পণ করবো এবং পরবর্তী তিনটির নামে তাকে আত্মসমর্পণ করতে হবে। তারা ঈশ্বরের কাছে অনুরোধ করবে যেন তিনি তা উদ্ধার করতে পারেন এবং আমরা আপনাকে আর কখনোই আপনাকে যেতে না পারি, আমরা পিতা, যদি আপনি করতে পারেন। তাহলে আমরা তোমার কাজ করবো, আমরা তোমাকে মুক্ত করে দেবো... ...আর তুমি যদি নবী হও, তুমি আঘাত করোনি।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ لَمَّا فُتِحَتْ ‏ ‏خَيْبَرُ ‏ ‏أُهْدِيَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَاةٌ فِيهَا سُمٌّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْمَعُوا لِي مَنْ كَانَ هَاهُنَا مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَجَمَعُوا لَهُ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي سَائِلُكُمْ عَنْ شَيْءٍ فَهَلْ أَنْتُمْ صَادِقِيَّ عَنْهُ قَالُوا نَعَمْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَبُوكُمْ قَالُوا أَبُونَا فُلَانٌ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتُمْ أَبُوكُمْ فُلَانٌ قَالُوا صَدَقْتَ ‏ ‏وَبَرَرْتَ ‏ ‏قَالَ لَهُمْ هَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ سَأَلْتُكُمْ عَنْهُ قَالُوا نَعَمْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏وَإِنْ كَذَبْنَاكَ عَرَفْتَ كَذِبَنَا كَمَا عَرَفْتَهُ فِي أَبِينَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَهْلُ النَّارِ قَالُوا نَكُونُ فِيهَا يَسِيرًا ثُمَّ تَخْلُفُونَنَا فِيهَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَخْلُفُكُمْ فِيهَا أَبَدًا ثُمَّ قَالَ لَهُمْ هَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ سَأَلْتُكُمْ عَنْهُ فَقَالُوا نَعَمْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ هَلْ جَعَلْتُمْ فِي هَذِهِ الشَّاةِ سُمًّا قَالُوا نَعَمْ قَالَ فَمَا حَمَلَكُمْ عَلَى ذَلِكَ قَالُوا أَرَدْنَا إِنْ كُنْتَ كَاذِبًا نَسْتَرِيحُ مِنْكَ وَإِنْ كُنْتَ نَبِيًّا لَمْ تَضُرَّكَ ‏","","",""],[9452,9452,"","আমরা যে যুক্তি নিয়ে কথা বলেছি, আমার বাবার সাথে কথা বলার চেষ্টা করে, ঈশ্বর তাকে একটা মই দিতে বলেছেন যে তার আশার কথা। আমি যা করছি তা হল মারা যাচ্ছি এবং আমি যা করছি তা হল, ঈশ্বর শুধু তাদের অনুসরণ করার চেয়ে আরও বেশি কিছু চান বা বেঁচে থাকুন ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ الْأَنْبِيَاءِ نَبِيٌّ إِلَّا قَدْ أُعْطِيَ مِنْ ‏ ‏الْآيَاتِ ‏ ‏مَا مِثْلَهُ آمَنَ عَلَيْهِ الْبَشَرُ وَإِنَّمَا كَانَ الَّذِي أُوتِيتُهُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ ‏","","",""],[9453,9453,"","আমরা তর্ক করেছি যে, আমি আমার বাবাকে খুশি করার কথা বলেছি কিন্তু আমার বাবা খুশি। আমার বাবা একজন দেবতা মানুষ, যে বলবে আমি সেই ব্যক্তি, যে আমি হবো। মুক্তভাবে বলতে পারো যে, আর শ্বাস থেকে ভয় না পাওয়া পর্যন্ত তুমি আমন্ত্রণ শুনতে চাও না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبَّادِ بْنِ أَبِي سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْأَرْبَعِ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دُعَاءٍ لَا يُسْمَعُ ‏","","",""],[9454,9454,"","আমি আমার স্বপ্নের কথা বলেছি যা বাবার চেয়ে আমি ভালো করেছি। বাবার সাথে, ঘোড়াটা ভাল, সে তাকে চুপ করিয়ে দেবার সিদ্ধান্ত নিল। আর একজন মই তাকে খুঁজে পাবে। আর আমি আমার বাবার স্বপ্নের কথা বলছি,","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ أَبِي عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏أَنَّهُ قَالَ صَلَّيْتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَوْقَ هَذَا الْمَسْجِدِ ‏ ‏فَقَرَأَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَسَجَدَ فِيهَا وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا ‏","","",""],[9455,9455,"","ঈশ্বর আমার প্রতি এক উত্তম ছেলেকে গড়ে তোলার বিষয়ে আমরা কথা বলেছিলাম । সে কিন্তু করবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يُنَجِّي أَحَدًا مِنْكُمْ عَمَلُهُ ‏ ‏فَقَالَ رَجُلٌ وَلَا أَنْتَ يَا رَسُولَ اللَّهِ فَقَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَتِهِ وَلَكِنْ ‏ ‏سَدِّدُوا ‏","","",""],[9456,9456,"","আমরা তর্কের কথা বলেছি যে আমাদের প্রভুর চেয়ে ভাল একটা ছেলেকে খুঁজে বের করতে হবে। এক বছরের মধ্যে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ سَنَةٍ ‏","","",""],[9457,9457,"","আমরা তর্কের কথা বলেছিলাম যে বাবা কথা শুনতে সাহায্য করছে, সে কথা বলার আগে সে আমার ছেলের কাছে একটা সিদ্ধান্ত নেবে, তারপর একটা ছেলে হবে। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি এমনকি তাঁর নিজের জন্যও প্রার্থনা করেছেন । যদি কালকের কথা কখনো বলো, তাহলে তাকে মেরে ফেলবে যদি তুমি ধরা পড়তে চাও। এমনকি আগামীকালও, আমার সাথে তোমার কোন সম্পর্ক নেই, তুমি টাকা চাও, তুমি দিতে। তুমি বলবে, ঈশ্বর এটা করেছেন। আমরা মসজিদের কাছে এসেছি, তারপর তিনি বললেন, আমি নিশ্চিত নই যে তাকে যেতে হবে এবং দেখতে হবে না। আমি তোমার ঋণের ব্যাপারে ক্লান্ত, আমি তোমাকে ভালোবাসি, আমার কল্পনা আমার, আর আমি আমার কল্পনাকে নিয়ে একবার যেতে চাই আর দেখি সে কি করেছে। সে যখন ফোন করে তখন সে চলে যায়। সে খারাপ ছেলে ছিল যে তাকে হত্যা করেছিল কিন্তু আমি তাকে একজন বধির মানুষের সাথে হাত দিতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْلًا قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فَجَاءَتْ بِرَجُلٍ مِنْ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏ثُمَامَةُ بْنُ أُثَالٍ ‏ ‏سَيِّدُ أَهْلِ ‏ ‏الْيَمَامَةِ ‏ ‏فَرَبَطُوهُ ‏ ‏بِسَارِيَةٍ ‏ ‏مِنْ ‏ ‏سَوَارِي ‏ ‏الْمَسْجِدِ فَخَرَجَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ مَاذَا عِنْدَكَ يَا ‏ ‏ثُمَامَةُ ‏ ‏قَالَ عِنْدِي يَا ‏ ‏مُحَمَّدُ ‏ ‏خَيْرٌ إِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ وَإِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ فَتَرَكَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَ الْغَدُ قَالَ لَهُ مَا عِنْدَكَ يَا ‏ ‏ثُمَامَةُ ‏ ‏قَالَ مَا قُلْتُ لَكَ إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ وَإِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ ‏ ‏فَتَرَكَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَانَ بَعْدَ الْغَدِ فَقَالَ مَا عِنْدَكَ يَا ‏ ‏ثُمَامَةُ ‏ ‏فَقَالَ عِنْدِي مَا قُلْتُ لَكَ إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ وَإِنْ تَقْتُلْ تَقْتُلْ ذَا دَمٍ وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ تُعْطَ مِنْهُ مَا شِئْتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْطَلِقُوا ‏ ‏بِثُمَامَةَ ‏ ‏فَانْطَلَقُوا بِهِ إِلَى نَخْلٍ قَرِيبٍ مِنْ الْمَسْجِدِ فَاغْتَسَلَ ثُمَّ دَخَلَ الْمَسْجِدَ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ يَا ‏ ‏مُحَمَّدُ ‏ ‏وَاللَّهِ مَا كَانَ عَلَى وَجْهٌ الْأَرْضِ أَبْغَضَ إِلَيَّ مِنْ وَجْهِكَ فَقَدْ أَصْبَحَ وَجْهُكَ أَحَبَّ الْوُجُوهِ كُلِّهَا إِلَيَّ وْ وَاللَّهِ مَا كَانَ مِنْ دِينٍ أَبْغَضَ إِلَيَّ مِنْ دِينِكَ فَأَصْبَحَ دِينُكَ أَحَبَّ الْأَدْيَانِ إِلَيَّ وَاللَّهِ مَا كَانَ مِنْ بَلَدٍ أَبْغَضَ إِلَيَّ مِنْ بَلَدِكَ فَأَصْبَحَ بَلَدُكَ أَحَبَّ الْبِلَادِ إِلَيَّ وَإِنَّ خَيْلَكَ أَخَذَتْنِي وَإِنِّي أُرِيدُ الْعُمْرَةَ فَمَاذَا ‏ ‏تَرَى فَبَشَّرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَهُ أَنْ يَعْتَمِرَ فَلَمَّا قَدِمَ ‏ ‏مَكَّةَ ‏ ‏قَالَ لَهُ قَائِلٌ ‏ ‏صَبَأْتَ ‏ ‏فَقَالَ لَا وَلَكِنْ أَسْلَمْتُ مَعَ ‏ ‏مُحَمَّدٍ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا وَاللَّهِ لَا ‏ ‏يَأْتِيكُمْ مِنْ ‏ ‏الْيَمَامَةِ ‏ ‏حَبَّةُ ‏ ‏حِنْطَةٍ ‏ ‏حَتَّى ‏ ‏يَأْذَنَ ‏ ‏فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9458,9458,"","আমরা একটা ছেলে সম্পর্কে কথা বলেছি যে কিনা কথা বলেছে। তার বাবা আর তার মেয়ের গৃহকর্মী যে তার মাকে ধোঁকা দিয়েছে বা কে তার মেয়ের সাথে বিশ্বাসঘাতকতা করেছে। বাবা অথবা তার চাচা, আমি বাবার এই কল্পনার কথা শুনেছি যে সে ঈশ্বরের কাছে যাবে... ...আর তাকে প্রভুর কাছে পেশ করা হবে. তার খালার মা আর মা'র মা-বাবাকে ছেড়ে চলে গেছে। তার সাথে ঐ মোটেল আর যারা এই আনন্দ করছিল.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ الرَّجُلِ يَجْمَعُ بَيْنَ الْمَرْأَةِ وَبَيْنَ خَالَةِ أَبِيهَا وَالْمَرْأَةِ وَخَالَةِ أُمِّهَا أَوْ بَيْنَ الْمَرْأَةِ وَعَمَّةِ أَبِيهَا أَوْ الْمَرْأَةِ وَعَمَّةِ أُمِّهَا ‏ ‏فَقَالَ قَالَ ‏ ‏قَبِيصَةُ بْنُ ذُؤَيْبٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُجْمَعَ بَيْنَ الْمَرْأَةِ وَخَالَتِهَا وَبَيْنَ الْمَرْأَةِ وَعَمَّتِهَا ‏ ‏فَنَرَى خَالَةَ أُمِّهَا وَعَمَّةَ أُمِّهَا بِتِلْكَ الْمَنْزِلَةِ وَإِنْ كَانَ مِنْ الرَّضَاعِ يَكُونُ مِنْ ذَلِكَ بِتِلْكَ الْمَنْزِلَةِ ‏","","",""],[9459,9459,"","আমি যখন ঘরে ফিরে আসি, তখন আমার বাবা আমাকে বলেন যে, তিনি একটা কুত্তার বাচ্চা । তারষরয় আল্লাহকে রক্ষা করেছে আর আমি বলবো তুমি চলে যাও আর তুমি চলে যাও আর তুমি চলে যাও আর ছুরিটা করো যখন তুমি তোমার পালাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَأْتُوهَا ‏ ‏تَسْعَوْنَ ‏ ‏وَأْتُوهَا تَمْشُونَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏","","",""],[9460,9460,"","আমরা একটা ছেলে ছেলের কথা বলেছিলাম যে আমার বাবা একজন যাজকের সাথে কথা বলতে চেয়েছিল, ঈশ্বর বলে দিয়েছেন যে আমার ছেলেকে বলেছে যে সে ওখানে আছে আর সে মিথ্যা বলে নি।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَالَ لِصَبِيٍّ تَعَالَ ‏ ‏هَاكَ ثُمَّ لَمْ يُعْطِهِ فَهِيَ كَذْبَةٌ ‏","","",""],[9461,9461,"","আমি মনে করি তুমি ঈশ্বরের কাছে প্রার্থনা কর... ...তিনি তার শান্তি রক্ষা করেছেন এবং আত্মসমর্পণ করেছেন। তারপর চলে গেল.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَنَا أَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ قَالَا وَكَانَ يُكَبِّرُ إِذَا رَكَعَ وَإِذَا قَامَ مِنْ السُّجُودِ وَإِذَا رَفَعَ رَأْسَهُ مِنْ السَّجْدَتَيْنِ ‏","","",""],[9462,9462,"","আমি আমার ভালবাসার ভালোর ব্যাপারে বাবাকে যা বলেছি তার থেকেও বেশি বলেছি। দোষ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لَا ‏ ‏يُبَالِي ‏ ‏الْمَرْءُ بِمَا أَخَذَ مِنْ الْمَالِ بِحَلَالٍ أَوْ بِحَرَامٍ ‏","","",""],[9463,9463,"","আমি বাবাকে দেখে খুশি যে আমি আমার বাবাকে পেয়ে খুশি হয়েছি। সে.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَدَعْ قَوْلَ ‏ ‏الزُّورِ ‏ ‏وَالْعَمَلَ بِهِ وَالْجَهْلَ فَلَيْسَ ‏ ‏لِلَّهِ حَاجَةٌ أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ ‏","","",""],[9464,9464,"","আমি আমার বাবাকে সাহায্য করার বিষয়ে যে তর্কের কথা বলেছিলাম, আমি তার কথা বলছি। আমি রাজা হতে চাই এবং আমি আপনাকে তা জিততে দিতে চাই না। ঈশ্বর যা করেছেন, ঈশ্বরের অধিকার হল তার প্রভু এবং ঈশ্বর তার প্রভু হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَمْرَانِ لَأَحْبَبْتُ أَنْ أَكُونَ عَبْدًا مَمْلُوكًا وَذَلِكَ أَنَّ الْمَمْلُوكَ لَا يَسْتَطِيعُ أَنْ يَصْنَعَ فِي مَالِهِ شَيْئًا وَذَلِكَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا خَلَقَ اللَّهُ عَبْدًا يُؤَدِّي حَقَّ اللَّهِ وَحَقَّ سَيِّدِهِ إِلَّا وَفَّاهُ اللَّهُ أَجْرَهُ مَرَّتَيْنِ ‏","","",""],[9465,9465,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি কী করতে পারি, তখন আমি তাকে সাহায্য করার জন্য কী করতে পারি? তিনি আমাকে বলেছিলেন যে, আমার বাবা বেন সিরেকে সাহায্য করার জন্য ভাল করবেন । সে.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يُوطِنُ ‏ ‏رَجُلٌ مُسْلِمٌ الْمَسَاجِدَ لِلصَّلَاةِ وَالذِّكْرِ إِلَّا ‏ ‏تَبَشْبَشَ ‏ ‏اللَّهُ بِهِ ‏ ‏يَعْنِي حِينَ يَخْرُجُ مِنْ بَيْتِهِ كَمَا ‏ ‏يَتَبَشْبَشُ ‏ ‏أَهْلُ الْغَائِبِ بِغَائِبِهِمْ إِذَا قَدِمَ عَلَيْهِمْ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[9466,9466,"","আমি আমার বাবাকে বলেছিলাম যে আমি ইঁদুর নিয়ে যাব, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি বলবে তিনি কি নিয়ে বসে আছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَحَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا جَلَسَ قَوْمٌ مَجْلِسًا لَمْ يَذْكُرُوا اللَّهَ فِيهِ وَلَمْ يُصَلُّوا عَلَى نَبِيِّهِمْ إِلَّا كَانَ عَلَيْهِمْ ‏ ‏تِرَةً ‏","","",""],[9467,9467,"","আমরা ঈশ্বরকে জিজ্ঞেস করেছিলাম যে, তিনি তা করতে চান আর তাকে গৌরবের আগুনে রক্ষা করা হয়েছিল । ঈশ্বরের কাছে প্রার্থনা করো, সে যেন আমাদের সাহায্য করে যখন আমরা তোমাকে আদেশ দিচ্ছি, আল্লাহ যেন তাকে শাস্তি না দেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏قَالَ بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْثٍ وَقَالَ إِنْ وَجَدْتُمْ ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏لِرَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَأَحْرِقُوهُمَا بِالنَّارِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَرَدْنَا الْخُرُوجَ ‏ ‏إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ تُحْرِقُوا ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏بِالنَّارِ وَإِنَّ النَّارَ لَا يُعَذِّبُ بِهَا إِلَّا اللَّهُ فَإِنْ وَجَدْتُمُوهُمَا فَاقْتُلُوهُمَا ‏","","",""],[9468,9468,"","আমি আমার বাবার শান্তির কথা কথা বলেছিলাম। কারণ আমার বাবা একজন পলাতক। সে বলছিল যে, ঈশ্বরের একজন মানুষকে আমরা বলি, \"ঈশ্বর\" সে আমাকে বলল আমি তাকে একজন পর্যটকের সাথে যোগাযোগ করব। এমনকি একবার তাকে জিততে দেখলেও তাকে করতে হবে। ভুত বলেছে যে আমি তোমাকে বলেছি ঈশ্বর এসে তাকে যেতে বলেছেন এবং আমি তাকে যেতে বলেছি। যারা ঈশ্বরের কাছে যাবেরের আওয়াজ শুনেছেন তারা বলেছেন আমি কোথাও ছিলাম না। পাথরটি পালিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَسَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَى ‏ ‏رَجُلٌ ‏ ‏مِنْ الْمُسْلِمِينَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَنَادَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَعْرَضَ عَنْهُ ‏ ‏فَتَنَحَّى ‏ ‏تِلْقَاءَ ‏ ‏وَجْهِهِ فَقَالَ لَهُ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَعْرَضَ عَنْهُ حَتَّى ثَنَّى ذَلِكَ عَلَيْهِ أَرْبَعَ مَرَّاتٍ ‏ ‏فَلَمَّا شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ دَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَبِكَ جُنُونٌ قَالَ لَا قَالَ فَهَلْ ‏ ‏أَحْصَنْتَ ‏ ‏قَالَ نَعَمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبُوا بِهِ ‏ ‏فَارْجُمُوهُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَأَخْبَرَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏كُنْتُ فِيمَنْ ‏ ‏رَجَمَهُ ‏ ‏فَرَجَمْنَاهُ ‏ ‏فِي الْمُصَلَّى فَلَمَّا ‏ ‏أَذْلَقَتْهُ ‏ ‏الْحِجَارَةُ هَرَبَ فَأَدْرَكْنَاهُ ‏ ‏بِالْحَرَّةِ ‏ ‏فَرَجَمْنَاهُ ‏","","",""],[9469,9469,"","আমরা কথা বলেছিলাম আমাকে সাহায্য করার জন্য, ঈশ্বরের দোহাই, সে এটা উদ্ধার করতে হবে, শুধু সময়মতো সে এটা উদ্ধার করতে পারবে এবং সে বছরের পর বছর ধরে রক্ষা পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏قَضَى ‏ ‏فِيمَنْ زَنَى وَلَمْ ‏ ‏يُحْصِنْ ‏ ‏أَنْ ‏ ‏يُنْفَى عَامًا مَعَ ‏ ‏الْحَدِّ ‏ ‏عَلَيْهِ ‏","","",""],[9470,9470,"","আমি যখন ঘরে ঘরে থাকতাম, তখন আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করি ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[9471,9471,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি তার আত্মার লোকেদের কাছে প্রার্থনা করেছিলেন । তার মুখের কথা অথবা তারা বলেছিল এটা করতে, তারা এটা করতে পারত, আমি তাদের শ্বাসে ডুবে আছি, যারা আপনার নিজের ইচ্ছামতোই ভ্রমণ করে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُؤْتَى بِالرَّجُلِ الْمُتَوَفَّى عَلَيْهِ دَيْنٌ فَيَسْأَلُ هَلْ تَرَكَ لِذَلِكَ مِنْ ‏ ‏قَضَاءٍ ‏ ‏فَإِنْ قَالُوا نَعَمْ إِنَّهُ تَرَكَ وَفَاءً صَلَّى عَلَيْهِ وَإِلَّا قَالَ لِلْمُسْلِمِينَ صَلُّوا عَلَى صَاحِبِكُمْ فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْفُتُوحَ قَامَ فَقَالَ ‏ ‏أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ فَمَنْ تُوُفِّيَ مِنْ الْمُؤْمِنِينَ فَتَرَكَ دَيْنًا فَعَلَيَّ قَضَاؤُهُ وَمَنْ تَرَكَ مَالًا فَهُوَ لِوَرَثَتِهِ ‏","","",""],[9472,9472,"","আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছিলাম। আমার বাবা তাকে ঈশ্বরের দোহাই দিয়ে শিখিয়েছিলেন যে তিনি তাকে উদ্ধার করতে বলেছেন না। আমি বললাম, তিনি ব্যর্থ হবেন না। আমি বলেছিলাম, ঈশ্বরের প্রেমের কথা। আমি বলেছিলাম, ঈশ্বরের প্রতি ভালবাসা নিয়ে কথা বলতে। আমি তাকে এটা করতে হবে। আমি তাকে বলেছি, আমি বলেছিলাম, আমি তাকে এটা করতে হবে। আমি এটা করতে চাই। আমি এটা করতে চাই। আমি এটা করতে চাই। কিন্তু আমি এটা করতে চাই। আমি মনে করি, আমি এটা করতে চাই। কিন্তু আমি এটা করতে চাই। কিন্তু আমি এটা করতে চাই। আমি এটা করতে চাই। কিন্তু আমি জানি না যে, আমি এটা করতে চাই। আমি এটা করি, আমি এটা করি। আমি এটা করি। আমি জানি, আমি জানি যে, আমি এটা করি, আমি এটা করি, আমি এটা করতে চাই। আমি এটা করি, আমি এটা আমার বাবা। আমি শুধু জানি যে, আমি এটা করতে চাই। আমি এটা করতে চাই। আমি শুধু তোমার কাছে একটা প্রশ্ন করি। তার কথা শুনে ভালো লাগলো, আমি বিশ্বাস করি।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ قِيلَ يَا رَسُولَ اللَّهِ وَمَا الْفَأْلُ قَالَ كَلِمَةٌ صَالِحَةٌ يَسْمَعُهَا أَحَدُكُمْ ‏","","",""],[9473,9473,"","আমরা তর্কের কথা বলেছি, একজন কুসুম্য পুত্র খুঁজে পাওয়ার জন্য আমাকে সাহায্য করার চেষ্টা করতে। ঈশ্বরের ইচ্ছা আছে এবং তিনি বলেছিলেন ঈশ্বর হলেন আল্লাহ্‌ যে বিজয়টা নিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[9474,9474,"","আমরা একটা ছেলের কথা বলেছিলাম যে সে আমাকে কিভাবে মারতে চাচ্ছে, হয়তো সে বাবাকে হারাহর বলেছে যে ঈশ্বর এটা রক্ষা করেছে আর সে কখনোই বলেনি সে ফিরে যেতে আর ফিরে যেতে আর ফিরে যেতে চায় এরপর একজন ভাল মানুষ হয়ে উঠতে পারে এবং একজন ভাল মানুষ হতে পারে । যতক্ষণ না সে তাকে কামড় দেয়... ...আর যখন সে যৌন কামনা থেকে আসে তখন সে কান্নায়.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ ثُمَّ يَقُولُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ حِينَ يَرْفَعُ ‏ ‏صُلْبَهُ ‏ ‏مِنْ الرَّكْعَةِ ثُمَّ يَقُولُ وَهُوَ قَائِمٌ رَبَّنَا لَكَ الْحَمْدُ ثُمَّ يُكَبِّرُ حِينَ يَهْوِي سَاجِدًا ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يُكَبِّرُ حِينَ يَهْوِي سَاجِدًا ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يَفْعَلُ ذَلِكَ فِي الصَّلَاةِ كُلِّهَا حَتَّى يَقْضِيَهَا وَيُكَبِّرُ حِينَ يَقُومُ مِنْ اللَّتَيْنِ بَعْدَ الْجُلُوسِ ‏","","",""],[9475,9475,"","আমরা একটি কুকুর ছেলের ব্যাপারে কথা বলেছি। এরপর সে বলল, আমরা আমার বাবার সাথে ছিলাম। সে বলেছিল আমরা তার আবেগ সম্পর্কে মানুষকে শিক্ষা দিচ্ছি। তিনি আপনাকে এমন শক্তি দেবেন যাতে মানুষ আপনাকে ক্ষমা করে। বিল্লা আপনার সাথে শেয়ার করবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنِ ‏ ‏ابْنِ دَارَّةَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏إِنَّا ‏ ‏لَبِالْبَقِيعِ ‏ ‏مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِذْ سَمِعْنَاهُ يَقُولُ أَنَا أَعْلَمُ النَّاسِ بِشَفَاعَةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْقِيَامَةِ قَالَ فَتَدَاكَّ النَّاسُ عَلَيْهِ فَقَالُوا إِيهٍ يَرْحَمُكَ اللَّهُ قَالَ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِكُلِّ عَبْدٍ مُسْلِمٍ لَقِيَكَ مُؤْمِنٌ بِي لَا يُشْرِكُ بِكَ ‏","","",""],[9476,9476,"","আমরা কথা বলেছি যে একজন শিকারীর কথা যারা শুনতে অথবা বলতে চেষ্টা করে যে আল্লাহকে শপথ গ্রহণ করতে হবে অথবা বলে যে বাবার প্রার্থনা এবং সালাদ তাদের দেখতে হবে। তারা দুই ডজন বার পিছনে ফিরে গেছে। ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তাকে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَكَرَهُ ‏","","",""],[9477,9477,"","আমরা একজন শিকারীর কথা বলেছি যে আমাকে এই ব্যাপারে শুনতে পেয়েছে, তাকে ছেড়ে দিতে হবে অথবা বলতে হবে যে সে-ই তার শ্বশুর আব্বা তার কাছে প্রার্থনা করেছে এবং তাকে টেনেছে যাদের কাছে আত্মসমর্পণ করতে হয়েছে?","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنْظُرُ إِلَيْهِ ‏","","",""],[9478,9478,"","ঈশ্বর তা দূর করতে পারেন এবং তিনি পাপ ও যাতনার জন্য মারা যাচ্ছেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَتَعَوَّذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ وَمِنْ عَذَابِ جَهَنَّمَ وَمِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[9479,9479,"","আমরা বাবার ভদ্র স্বপ্ন নিয়ে কথা বলেছি, যার ছেলে আছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيُذَادَنَّ ‏ ‏نَاسٌ مِنْ أَصْحَابِي عَنْ الْحَوْضِ كَمَا ‏ ‏تُذَادُ ‏ ‏الْغَرِيبَةُ مِنْ الْإِبِلِ ‏","","",""],[9480,9480,"","আমরা তর্ক করেছি যে আমরা ভালোবাসার একটা আবেগ শুনতে চাই, ভাববাদী প্রার্থনা করলেন পানি দিয়ে তা উদ্ধার করতে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ جُحَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ كَسْبِ الْإِمَاءِ ‏","","",""],[9481,9481,"","আমরা একটা ঘোড়ার ছেলের ব্যাপারে কথা বলেছি, আমার বাবার নামে একজন পলাতকের কথা, যে তার নাম শুনেছে, অথবা বলে দেবে যে শপথ করে তার কাছে প্রার্থনা করেছে সে আহতদের দিকে এগিয়ে যাবে, মাটিতে নিয়ে যাবে, পঞ্চম চেয়ারের সেতুর মধ্যে একটা সেতু বলছে যে দাঙ্গা শোনা যায়নি যে স্তম্ভগুলো ঈর্ষা করছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَجْمَاءُ ‏ ‏جَرْحُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏مَا سَمِعْتُ أَحَدًا يَقُولُ ‏ ‏الرَّكَائِزَ ‏ ‏غَيْرَهُ ‏","","",""],[9482,9482,"","আমরা তর্কের কথা বলেছি যে বাবার ছেলেকে যেতে বলেছি আর বাবাকে আমার বাবার ছেলের কষ্ট পেতে বলেছে। আমার বাবা ভালো ঈশ্বরের হয়ে ভালোর জন্য।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏","","",""],[9483,9483,"","ঈশ্বর আমাকে বলেন যে, আপনি জগৎকে ঐক্যবদ্ধ করার জন্য এক ভয়পূর্ণ প্রচেষ্টা করতে চান ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَفْضُلُ صَلَاةُ الْجَمَاعَةِ عَلَى صَلَاةِ الْوَحْدَةِ سَبْعًا وَعِشْرِينَ دَرَجَةً ‏ ‏أَوْ خَمْسًا وَعِشْرِينَ دَرَجَةً ‏","","",""],[9484,9484,"","ঈশ্বর দাবি করেছেন যে, যদি তিনি পানির জন্য ঘোমটা লিখে থাকেন, তাহলে তাকে আত্মসমর্পণ করতে হবে, তারপর তাকে যেতে দেয়া হয়েছে। যাও।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏دَعَا بِمَاءٍ ‏ ‏فَاسْتَنْجَى ‏ ‏ثُمَّ مَسَحَ ‏ ‏بِيَدِهِ ‏ ‏عَلَى الْأَرْضِ ثُمَّ تَوَضَّأَ ‏","","",""],[9485,9485,"","বাবা বাবার ছেলেকে নিয়ে আমাদের কথা বলেছিলেন। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তাকে মৃতদের উদ্ধার করেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ وَمَنْ حَمَلَهُ فَلْيَتَوَضَّأْ ‏","","",""],[9486,9486,"","আমি যখন তাকে বলেছিলাম যে, আমি একজন যিহোবার সাক্ষি । আমরা তার ব্যবসা নিয়ে কথা বলেছি.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلْمِ بْنِ عَبْدِ الرَّحْمَنِ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَسَمَّى بِاسْمِي فَلَا ‏ ‏يَتَكَنَّى بِكُنْيَتِي وَمَنْ تَكَنَّى بِكُنْيَتِي فَلَا ‏ ‏يَتَسَمَّى بِاسْمِي ‏ ‏حَدَّثَنَاه ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[9487,9487,"","আমরা তর্ক করেছি আর সে আমার বাবার বাবার কথা বলেছে. সে বলল যে সে ঈশ্বরের কাছে প্রার্থনা করেছে আর যে কেউ প্রার্থনা করেছে তাকে উদ্ধার করেছে. মসজিদের অন্ত্যেষ্টিক্রিয়ার কিছু একটা খুঁজে পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فِي الْمَسْجِدِ فَلَا شَيْءَ لَهُ ‏","","",""],[9488,9488,"","আমরা তর্কের কথা বলেছি যে আমার বাবা মুক্ত হয়ে যাওয়া নিয়ে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর বলবেন যে সেই সমস্ত মানুষের আত্মা থেকে যারা আসবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏مِنْ شِرَارِ النَّاسِ ذَا الْوَجْهَيْنِ الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ ‏","","",""],[9489,9489,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছিলাম এবং তিনি বলেছিলেন যে, তিনি এমন একজন হবেন, যিনি যাচ্ছেন । যে কেউ একজন হতে যাচ্ছে সে হতে যাচ্ছে সে হতে যাচ্ছে যে কিনা হতে যাচ্ছে সেই হতে যাচ্ছে যে হতে যাচ্ছে সে হতে যাচ্ছে। সে এমন একজন যে হতে যাচ্ছে সে হবে সে হবে সেই হবে সেই হবে যে কিনা হবে সেই হবে। আমি লোনারদের চাবি নিয়ে ঘুমাচ্ছি, যাদের রাখা হয়েছিল। আমার হাতে.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بُعِثْتُ ‏ ‏بِجَوَامِعِ الْكَلِمِ ‏ ‏وَنُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَبَيْنَمَا أَنَا نَائِمٌ أُتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدَيَّ ‏","","",""],[9490,9490,"","আমরা তর্ক করেছি যে আমার বাবার ছেলে ঈশ্বরের নামে কথা বলেছি, সে বলছে বাবা হারাহরের কথা, সে বলছে সে ঈশ্বরের কাছে প্রার্থনা করছে তার শান্তি এবং তার শান্তির কথা চিন্তা করা উচিত। তার অন্য আলো, তাকে কাউকে বলতে হবে তাকে মারতে অথবা তাকে প্রতিরোধ করতে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَحْتَزِمَ أَحَدُكُمْ حُزْمَةَ حَطَبٍ فَيَحْمِلَهَا عَلَى ظَهْرِهِ فَيَبِيعَهَا خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ رَجُلًا يُعْطِيهِ أَوْ يَمْنَعُهُ ‏","","",""],[9491,9491,"","আমরা যে আবেগ নিয়ে কথা বলেছি তা আমাদের হৃদয়ের ক্ষতি করেছে, ঈশ্বর এটা উদ্ধার করতে হবে যদি সে ঘুম থেকে উঠে উঠে উঠে উঠে, সে জানে কোথায় সে তার হাত শুরু করেছে। - আমার থেকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَلَا يَغْمِسْ يَدَهُ فِي إِنَائِهِ حَتَّى يَغْسِلَهَا ثَلَاثًا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ مِنْهُ ‏","","",""],[9492,9492,"","আমরা কামনার প্রতি আবেগ এবং প্রয়োজনের কথা বলেছি যে আমরা আপনার অকুতোর আওয়াজ শুনেছি। লর্ড তার জন্য প্রার্থনা করেছেন এবং তিনি শহরে বললেন বৃক্ষ সাত বছর বয়সী এক ব্যক্তির ছায়ার মধ্যে যাত্রীর বয়ে আনবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الضَّحَّاكِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ إِنَّ ‏ ‏فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا سَبْعِينَ ‏ ‏أَوْ مِائَةَ سَنَةٍ ‏ ‏هِيَ شَجَرَةُ الْخُلْدِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَوْ مِائَةَ سَنَةٍ شَجَرَةُ الْخُلْدِ ‏ ‏قُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏هِيَ شَجَرَةُ الْخُلْدِ قَالَ لَيْسَ فِيهَا هِيَ ‏","","",""],[9493,9493,"","আমরা কামনা নিয়ে কথা বলেছি যে আমরা একটা দাঙ্গার সৃষ্টি করেছি যা একবার আমাদের বলেছিল যে আমরা একে অন্যকে বলার চেষ্টা করেছি। আমি বলেছি ঈশ্বর আপনাকে দয়া করে জেলে বন্দী করেছেন, ঈশ্বর আমি, ঈশ্বর, আমি কেটেছি, সে তার স্বামীকে বলবে না সে তোমাকে ধরে ফেলবে এবং তোমাকে কেটে ফেলবে পাহাড়ের গুণ্ডারা বলেছে, আমি এই অশুভ লক্ষণের সিংহাসনের কথা শুনেছি, আল্লাহ তার কাছে প্রার্থনা করেছেন এবং তিনি বললেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الْجَبَّارِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ إِنَّ الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ تَقُولُ يَا رَبِّ إِنِّي قُطِعْتُ يَا رَبِّ إِنِّي ظُلِمْتُ يَا رَبِّ إِنِّي أُسِيءَ إِلَيَّ يَا رَبِّ يَا رَبِّ فَيُجِيبُهَا رَبُّهَا عَزَّ وَجَلَّ فَيَقُولُ ‏ ‏أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الْجَبَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَلِكَ ‏","","",""],[9494,9494,"","আমরা আমাদের আবেগ-ভাবনার কথা বলেছি যা আমাদেরকে আমাদের নিজেদের অনুসন্ধান চালিয়ে নিয়ে এসেছে। ঈশ্বর বলেছেন, ঈশ্বর আছেন যিনি আমার মায়ের কথা বলেছেন যে তিনি হবেন সেই হবে সেই হবে সেই ব্যক্তি যে হবে। যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে হবে পুরুষ হবে নিরাপদ , যে ব্যক্তি হতে পারে সেই হবে সেই ব্যক্তি যে রাজা হবে । ভাল মানুষ হিসাবে, প্রথম থেকে পালাতে ১০০ বার লাগে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ فِي أُمَّتِي مِنْ أَمْرِ الْجَاهِلِيَّةِ لَنْ يَدَعُوهُنَّ ‏ ‏التَّطَاعُنُ ‏ ‏فِي الْأَنْسَابِ ‏ ‏وَالنِّيَاحَةُ ‏ ‏وَمُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا ‏ ‏وَالْعَدْوَى ‏ ‏الرَّجُلُ يَشْتَرِي الْبَعِيرَ الْأَجْرَبَ فَيَجْعَلُهُ فِي مِائَةِ بَعِيرٍ فَتَجْرَبُ فَمَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[9495,9495,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা আমাদের জন্য এক সমস্যা তৈরি করেছে, কারণ ভবিষ্যদ্বাণীর জন্য তাকে একটা উপহার প্রদান করা হয়েছে এবং তিনি আত্মসমর্পণ করবেন যদি প্রার্থনা মূল্য হয় নীরবতা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَرْقَاءَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةَ ‏","","",""],[9496,9496,"","আমরা আবেগ আর আবেগ নিয়ে কথা বলেছি যে আমরা একটা মিল পেয়েছি যেটা তার কাজ হয়েছে। আমার বাবা আমার কথা বলেছেন। বাবা ঈশ্বরের লোক, সে হাল ছেড়ে দিত এবং আরো বেশি খেতে পারত এবং সে যদি তাকে বলতে পারত যে, সাত পায়ে কাঁঠে খায় এবং একদিন তার সাথে একদিন পৃথিবীর সবচেয়ে গুরুত্বপূর্ণ জিনিস হল খাবার।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏الْمَعْنَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ كَافِرٌ فَكَانَ يَأْكُلُ أَكْلًا كَثِيرًا ثُمَّ إِنَّهُ أَسْلَمَ فَكَانَ يَأْكُلُ أَكْلًا قَلِيلًا فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ ‏ ‏الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَإِنَّ الْمُسْلِمَ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[9497,9497,"","আমি আমার বাবার কাছে সবসময় এই বলে কথা শুনেছি যে, সে যেন তার বাবার জন্য এক দেবতা । যদি তুমি এটার উত্তরাধিকারী হও এবং যে তার আনুগত্য ত্যাগ করে একে অপরকে ছেড়ে দাও, তাহলে তুমি আমাদের সবাইকে ছেড়ে দিবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ وَمَنْ تَرَكَ كَلًّا وُلِّيتُهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَمَنْ تَرَكَ كَلًّا فَإِلَيْنَا ‏","","",""],[9498,9498,"","আমরা আবেগ-অনুভূতি নিয়ে কথা বলেছি এবং একটি রাজধানী সম্পর্কে আমরা কথা বলেছি যেখানে যাওয়ার নির্দেশ আছে। ঈশ্বর আদেশ দিয়েছেন এবং তারা বলেন যে আমরা ঈশ্বর ঈশ্বরের নামে কথা বলো। আর যদি আমাদের অসুস্থ হয়ে পড়া উচিৎ, সে কিছু একটা বলে যা আমরা শুধু বলেছিলাম, তাহলে আমরা আবার যুদ্ধ করার চেষ্টা করেছি। সে বলল, ঈশ্বর জয়ী হয়েছেন এবং আমরা কথা বলেছি। কীভাবে তিনি আমাকে থামাতে চেষ্টা করেছিলেন, ঈশ্বর বাবার সাথে ডেটিং করছিলেন, আমার মা আমাকে নিয়ে কথা বলছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أَحَدَنَا يُحَدِّثُ نَفْسَهُ بِالشَّيْءِ مَا يُحِبُّ أَنَّهُ يَتَكَلَّمُ بِهِ وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ قَالَ ذَاكَ ‏ ‏مَحْضُ ‏ ‏الْإِيمَانِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏بِإِسْنَادِهِ قَالَ ‏ ‏مِنْ شَأْنِ الرَّبِّ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الرَّبِيعِ ‏ ‏وَكَانَ يُقَاعِدُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ فِي أُمَّتِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏","","",""],[9499,9499,"","আমরা হিংসার কথা বলেছি... ...আমরা এক চতুর্থাংশের কথা বলেছি, আকাশে একটা ঘোড়া পাওয়া যাবে, যদি সে শপথ করে থাকে, আমি তাকে হত্যা করতে বলবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْأَصْغَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏قَالَ فَسَأَلْتُهُ فَقَالَ سَجَدَ فِيهَا خَلِيلِي وَلَا أَزَالُ أَسْجُدُ حَتَّى أَلْقَاهُ ‏","","",""],[9500,9500,"","আমরা এমন এক আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমাদের কাছে হয়েছে, যেন আমাদের ঈশ্বর সম্বন্ধে কিছু করার চেষ্টা করে। তারা বলেছিল যে তার কাছে ভালো কিছু ছিল আর যদি তিনি ঠিক হয়ে থাকতেন এবং বলেছিলেন যে তারা ভুল করেছে তাহলে তারা তা করবে। আমরা বুঝতে পেরেছি যে, যদি তারা তার বয়স থেকে কখনো হারাবে না। তাকে মেরে ফেলতে হবে না তোমার ভাই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ لِرَجُلٍ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَقٌّ فَأَغْلَظَ لَهُ فَهَمَّ بِهِ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا وَقَالَ لَهُمْ اشْتَرُوا لَهُ ‏ ‏سِنًّا ‏ ‏فَأَعْطُوهُ فَقَالُوا إِنَّا لَا نَجِدُ إِلَّا ‏ ‏سِنًّا ‏ ‏أَفْضَلَ مِنْ ‏ ‏سِنِّهِ ‏ ‏فَقَالَ اشْتَرُوا لَهُ فَأَعْطُوهُ فَقَالَ ‏ ‏إِنَّ مِنْ خَيْرِكُمْ ‏ ‏أَوْ خَيْرُكُمْ ‏ ‏أَحْسَنَكُمْ قَضَاءً ‏","","",""],[9501,9501,"","আমরা একটি আবেগ কথা বলেছি যে আমাদের কাছে বাবার দৃঢ় সংকল্পের জন্য অনুপ্রেরনা বয়ে এনেছে একটি পরী দেবী খুঁজে পেতে। তিনি একবার এটাকে উঠিয়ে নিয়েছিলেন এবং পরে তিনি সেটা বড় করেছিলেন যখন তিনি বললেন, তিনি বললেন, সে তিন ঘটনার পর আর ভেঙ্গে যায়নি, সে আগুন জ্বালিয়ে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏رَفَعَهُ مَرَّةً ثُمَّ لَمْ يَرْفَعْهُ بَعْدُ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ ثَلَاثٍ ‏ ‏أَوْ فَوْقَ ثَلَاثٍ ‏ ‏فَمَنْ هَاجَرَ بَعْدَ ثَلَاثٍ ‏ ‏أَوْ فَوْقَ ثَلَاثٍ ‏ ‏فَمَاتَ دَخَلَ النَّارَ ‏","","",""],[9502,9502,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি যে আমরা একটি শিকারী একটি প্রথা আনা হয়েছে যে যে যে শুনতে অথবা যে শুনতে অথবা শুনতে পায়, ঈশ্বর প্রভু এবং অনুগ্রহ এবং অনুগ্রহ প্রদান করেছেন তোমার প্রভুর অনুগ্রহ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جَرْحُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[9503,9503,"","আমরা আমাদের আবেগ মুক্ত করতে চেষ্টা করেছি... ...যেটা আমাদের হৃদয়ের মধ্যে একটা বাপ্তিস্মের আওয়াজ এনেছে যেটা শুনতে একটা ঘোড়াকে বলতে শুনেছি, তার জন্য প্রার্থনা করছে, আর সে বলছে যে, ঈশ্বর তার জন্য প্রার্থনা করছে তিনি আমার মায়ের সাত শব্দ থেকে পাগল হয়ে যাচ্ছেন। ঈশ্বর দাবি করেছেন, ঈশ্বর তাকে এটা করতে বলেছেন। তিনি বলেন, \"ঈশ্বর আমাকে দাবি করেছেন, ঈশ্বর আমাকে তাদের থেকে আলাদা করে বলবেন।\" তিনি বললেন, \"ঈশ্বর আমাকে এসব বলার জন্য ছেড়ে চলে যেতে বলেছেন।\" তিনি বলেন, \"ঈশ্বর আমার মায়ের কাছে দাবি করেছেন।\" তিনি বললেন, \"আমি যদি আমার মায়ের সাতটা ঠিক করে দেন, আমি জানি, \"আমি জানি না যে, আমি এটা করতে চাই।\" এবং আমি যদি আমার মায়ের কথা বলি, তাহলে আমি তাকে বলতে চাই, আমি জানি না যে, আমি জানি না। আমি যদি আমার মায়ের কাছে ক্ষমা চাই, আমি জানি, আমি জানি, আমি জানি, আমি জানি না যে, আমি জানি, আমি জানি না যে, আমি জানি, আমি যদি আমার মায়ের কথা বলছি, \"ঈশ্বর আমাকে \"ঈশ্বর\" যে আপনার সমস্যা আছে।\"","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ زِيَادٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ قَالَ فَقَالَ ‏ ‏عُكَّاشَةُ ‏ ‏يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْهُ مِنْهُمْ قَالَ فَقَامَ رَجُلٌ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ فَقَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏","","",""],[9504,9504,"","আমরা আবেগ নিয়ে কথা বলেছি এবং এমন একটা প্রয়োজন যার কথা আমরা শুনেছি ঘোড়ার একজন আসামীর কথা, যে এটা শুনতে চায়। ঈশ্বরের দোহাই তাকে আদেশ দিয়েছে এবং তাকে তীর্থযাত্রী দেয়া হয়েছে। অথবা সে তোমাকে ভয় পায় না, ঈশ্বর তাকে আগে থেকেই দেখেছেন... ...অথবা তার ছবি পাথরের মত... ...যদি সে গৃহিনী আর পশুটাকে আড়াল করে, তাহলে সে একটা অদ্ভুত চমক।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَوْ قَالَ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏أَمَا ‏ ‏يَخْشَى أَلَا ‏ ‏يَخْشَى أَحَدُكُمْ أَنْ يَجْعَلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ أَوْ صُورَتَهُ صُورَةَ حِمَارٍ إِذَا رَفَعَ رَأْسَهُ قَبْلَ الْإِمَامِ وَالْإِمَامُ سَاجِدٌ ‏","","",""],[9505,9505,"","আমরা এমন এক অতিমানবের বিষয়ে কথা বলেছিলাম, যিনি গোপন একটা রহস্য বলেছিলেন । তারা তার খেলা দেখতে যাচ্ছে আর আমি তিন সেকেন্ডের মধ্যে গুনবো, তুমি ভাবছ হলে হলের অবস্থাও তাই হবে","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ وَلَا تُفْطِرُوا حَتَّى تَرَوْا الْهِلَالَ وَقَالَ صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غَبِيَ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَكْثَرُ عِلْمِي أَنَّهُ قَالَ لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ وَلَا تُفْطِرُوا حَتَّى تَرَوْا الْهِلَالَ ‏","","",""],[9506,9506,"","আমরা আবেগ-অনুভূতি নিয়ে কথা বলেছি এবং একটি দুঃখজনক ফুল দিয়ে আমরা বাপ্তিস্মের অনুষ্ঠান গড়েছি। ঈশ্বর একটি তীর্থযাত্রার কথা বলেছেন, বাবা বলেছেন তিনি শুনেছেন তিনি বলেন যে, যখন একজন ব্যক্তি মুখ দিয়ে হেঁটে যায়, তখন সে তার মিত্রদের এক গৌরবময় পোশাক পরে । একা.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي وَعَلَيْهِ ‏ ‏حُلَّةٌ ‏ ‏مُرَجِّلًا ‏ ‏جُمَّتَهُ ‏ ‏تُعْجِبُهُ نَفْسُهُ إِذْ خُسِفَ بِهِ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِي الْأَرْضِ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏إِذْ خَسَفَ اللَّهُ بِهِ ‏","","",""],[9507,9507,"","আমি আমার বাবার অহংকারের কথা বলেছি, তোমাকে যা খেতে হবে তা সে আমাকে দেবে যখন আমি তোমাকে লেখার আগে খেয়ে ফেলি। আমি জানি, আমি যা করেছি তা করার জন্য। আমি জানি, আমি যা করেছি তা করার জন্য। তুমি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا أُهْلِكَ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏قَبْلَكُمْ ‏ ‏أَوْ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بِكَثْرَةِ اخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ وَكَثْرَةِ سُؤَالِهِمْ فَانْظُرُوا مَا أَمَرْتُكُمْ بِهِ فَاتَّبِعُوهُ مَا اسْتَطَعْتُمْ وَمَا نَهَيْتُكُمْ عَنْهُ فَدَعُوهُ ‏ ‏أَوْ ذَرُوهُ ‏","","",""],[9508,9508,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি যে, আমরা আমার বাবার হাতে একটি অনুভূতি পেয়েছি তিনি আপনার জন্য ছেড়ে দেব এবং আমি যে সমস্ত কাজ করি তার জন্য তিনি ছেড়ে দেবেন এবং আমি যে কাজ করি তার জন্য আমি সবার জন্য, এবং আমার জন্য যে সমস্ত কাজ করি তার জন্য আমরা এখানে আটকে আছি, আশীর্বাদের উপর।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّكُمْ عَزَّ وَجَلَّ ‏ ‏كُلُّ الْعَمَلِ ‏ ‏كَفَّارَةٌ ‏ ‏وَالصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[9509,9509,"","আমরা এক আবেগে বাপ্তাইজিত হয়েছি, যে বলছে আমার বাবার হাতে আমরা একটা অনুভূতি পেয়েছি, ঈশ্বরকে ভালোবাসার জন্য তাকে ছেড়ে দেয়া হয়েছে, যেভাবে তারা যেতে পারে যেভাবে তারা অপরাধীর হাতে ঢুকে পরে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَجِبَ اللَّهُ مِنْ أَقْوَامٍ يُجَاءُ بِهِمْ فِي السَّلَاسِلِ حَتَّى يَدْخُلُوا الْجَنَّةَ ‏","","",""],[9510,9510,"","সবচেয়ে উঁচু ও অটল, সন্দেহের মধ্যে সন্দেহ রয়েছে কিন্তু লোকেদের গান গাইতে হবে না । মানুষ লজ্জা পায়।","‏ ‏وَبِالْإِسْنَادِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الْأُكْلَةُ وَالْأُكْلَتَانِ وَاللُّقْمَةُ وَاللُّقْمَتَانِ ‏ ‏أَوْ التَّمْرَةُ وَالتَّمْرَتَانِ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ فِي اللُّقْمَةِ وَالتَّمْرَةِ ‏ ‏وَلَكِنَّ الْمِسْكِينَ الَّذِي لَيْسَ لَهُ غِنًى يُغْنِيهِ وَلَا يَسْأَلُ النَّاسَ ‏ ‏إِلْحَافًا ‏ ‏أَوْ يَسْتَحِي أَنْ يَسْأَلَ النَّاسَ ‏ ‏إِلْحَافًا ‏","","",""],[9511,9511,"","আর সে এটাকে আগুনেই ডেকেছে, একটা বিড়ালের মধ্যে একজন মহিলাও তাকে খেতে দেয়নি।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏دَخَلَتْ النَّارَ امْرَأَةٌ فِي هِرَّةٍ رَبَطَتْهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ ‏","","",""],[9512,9512,"","আর এই সম্প্রদায়ের প্রতি এক ঘন্টার জন্য আহ্বান করে, আমি কখনোই এমন এক শান্তির ভিত্তি হতে চাই না, যা ঈশ্বর অবিবাহিত।","‏ ‏وَبِالْإِسْنَادِ ‏ ‏إِنَّ ‏ ‏فِي الْجُمُعَةِ لَسَاعَةً لَا ‏ ‏يُوَافِقُهَا ‏ ‏عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ فِيهَا خَيْرًا إِلَّا أَعْطَاهُ إِيَّاهُ ‏","","",""],[9513,9513,"","আর সে আমাকে বলে যে আমি যা যেতে চাই তাই করতে চাই অথবা বলতে চাই আমি যেতে চাই। অথবা আমি যদি যেতে চাই, তাহলে দুই জন্য একটা কাঁদব, তাকে গুলি করতে নয়।","‏ ‏وَبِالْإِسْنَادِ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا أُحِبُّ أَنَّ لِي مِثْلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ مَا أُحِبُّ أَنَّ لِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا ‏ ‏أَدَعُ ‏ ‏يَوْمَ أَمُوتُ دِينَارًا إِلَّا أَنْ ‏ ‏أُرْصِدَهُ ‏ ‏لِدَيْنٍ ‏","","",""],[9514,9514,"","আমরা কিছু স্নায়ু মুক্ত করতে চেষ্টা করেছি যে আমরা শুনানি একটি রীতি তৈরি করেছি. আমার বাবা তার কাছে প্রার্থনা করেছেন এবং তার নাম এবং আমার নাম প্রকাশ করা হবে বাক।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ النَّخَعِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[9515,9515,"","তিনি বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করতে যাচ্ছেন আর তিনি ভয় বা ঈশ্বরের রূপ পুনরাবৃত্তি করবেন । ভালোর মঙ্গল করো।","‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ ‏ ‏الشِّكَالَ ‏ ‏مِنْ الْخَيْلِ ‏ ‏أَوْ الْأَشْكَالَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏شُعْبَةُ ‏ ‏يُخْطِئُ فِي هَذَا الْقَوْلِ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏سَلْمُ بْنُ عَبْدِ الرَّحْمَنِ النَّخَعِيُّ ‏","","",""],[9516,9516,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা যা শুনেছি তা শোনার রীতি নিয়ে, ঈশ্বরের কথা বলা মানে হলো, বিশ্বাস সুরক্ষিত রাখা আর দুঃখ এখন শেষ। সূর্য, ঈশ্বর ভিলেনদের পরাজিত করেছেন... ...আমি ভয়ংকর আর ভয়ঙ্কর... ...আর একজন রানীর সামনে এসে তাকে মারল... সূর্যটা এখানে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْكُفْرُ مِنْ قِبَلِ الْمَشْرِقِ وَإِنَّ ‏ ‏السَّكِينَةَ ‏ ‏فِي أَهْلِ الْغَنَمِ وَإِنَّ ‏ ‏الرِّيَاءَ ‏ ‏وَالْفَخْرَ فِي أَهْلِ ‏ ‏الْفَدَّادِينَ ‏ ‏أَهْلِ ‏ ‏الْوَبَرِ ‏ ‏وَأَهْلِ الْخَيْلِ وَيَأْتِي ‏ ‏الْمَسِيحُ ‏ ‏مِنْ قِبَلِ الْمَشْرِقِ وَهِمَّتُهُ ‏ ‏الْمَدِينَةُ ‏ ‏حَتَّى إِذَا جَاءَ ‏ ‏دُبُرَ ‏ ‏أُحُدٍ ‏ ‏تَلَقَّتْهُ الْمَلَائِكَةُ فَضَرَبَتْ وَجْهَهُ قِبَلَ ‏ ‏الشَّامِ ‏ ‏هُنَالِكَ يُهْلَكُ هُنَالِكَ يُهْلَكُ ‏","","",""],[9517,9517,"","আমরা আবেগ কথা বলেছি যে আমরা ঈশ্বরের কথা শোনার রীতি নিয়ে এসেছি, ঈশ্বর আমাদের কাছে যা কিছু করেছেন তা দিতে বলেছেন, আপনি আমার সাথে বা আপনি যা করতে যাচ্ছেন না তাই করতে হবে। ( যোহন ১৪: ৩০) লোকেদের অশ্রুশসরণ করা হল অজাতের মধ্যে সবচেয়ে ভাল ব্যক্তি । যে কিনা মাটিতে ছিল এবং তার জীবনের অনেক কিছু ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا تَطْلُعُ الشَّمْسُ بِيَوْمٍ وَلَا تَغْرُبُ بِأَفْضَلَ ‏ ‏أَوْ أَعْظَمَ ‏ ‏مِنْ يَوْمِ الْجُمُعَةِ وَمَا مِنْ دَابَّةٍ إِلَّا تَفْزَعُ لِيَوْمِ الْجُمُعَةِ إِلَّا هَذَانِ الثَّقَلَانِ مِنْ الْجِنِّ وَالْإِنْسِ وَعَلَى كُلِّ بَابٍ مَلَكَانِ يَكْتُبَانِ الْأَوَّلَ فَالْأَوَّلَ كَرَجُلٍ قَدَّمَ ‏ ‏بَدَنَةً ‏ ‏وَكَرَجُلٍ قَدَّمَ بَقَرَةً وَكَرَجُلٍ قَدَّمَ شَاةً وَكَرَجُلٍ قَدَّمَ طَيْرًا وَكَرَجُلٍ قَدَّمَ بَيْضَةً فَإِذَا قَعَدَ الْإِمَامُ طُوِيَتْ الصُّحُفُ ‏","","",""],[9518,9518,"","আমরা যে আবেগ নিয়ে কথা বলেছি তা আমাদের কানে তুলে এনেছে যে আমি হয়ত তার সাথে কথা বলতে চাই, যদি সে তিন বার দেখা না করে, ঈশ্বরকে জিজ্ঞেস করো আর টাকা জমাও, সে আরো বেশি বিখ্যাত হবে আর সে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَظْهَرَ ثَلَاثُونَ دَجَّالُونَ كُلُّهُمْ يَزْعُمُ أَنَّهُ رَسُولُ اللَّهِ ‏ ‏وَيَفِيضَ ‏ ‏الْمَالُ فَيَكْثُرَ وَتَظْهَرَ ‏ ‏الْفِتَنُ ‏ ‏وَيَكْثُرَ ‏ ‏الْهَرْجُ ‏ ‏قَالَ قِيلَ وَأَيُّمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ الْقَتْلُ ثَلَاثًا ‏","","",""],[9519,9519,"","আমরা কামনার কথা বলেছি যে আমরা ঈশ্বরের কথা শুনেছি, ঈশ্বরের কথা শোনার রীতি নিয়ে। আল্লাহ তাঁর কাছে প্রার্থনা করেছেন এবং বলেছেন তিনি সকল প্রার্থনা শোনেন না। বইয়ের অন্ধকার হচ্ছে গাল, যাও।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏غَيْرُ تَمَامٍ ‏","","",""],[9520,9520,"","আমরা কামনার কথা বলেছি যে, আমরা ঈশ্বরের কথা শুনে একটা রীতি নিয়ে এসেছি, ঈশ্বর তাকে জিজ্ঞেস করেছেন আর সে তার ভাইয়ের মঠ আর তার ভাইয়ের মঠে থাকবে না তার পাপের উপর কোন পরিকল্পনা নেই.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسْتَامُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبُ عَلَى خِطْبَتِهِ ‏","","",""],[9521,9521,"","আর সে তার বাবাকে ফোন করবে যে তার কাছে প্রার্থনা করেছিল আর সে ঈশ্বরের নামে কসম করল যে সে জিতবে। ঈশ্বর জিতে গেছে আর তাকে যা দিয়েছি তা কখনো অসম্ভব হবে না।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا دَعَا أَحَدُكُمْ فَلَا يَقُولَنَّ اللَّهُمَّ إِنْ شِئْتَ وَلَكِنْ ‏ ‏لِيُعْظِمْ رَغْبَتَهُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَتَعَاظَمُ عَلَيْهِ شَيْءٌ أَعْطَاهُ ‏","","",""],[9522,9522,"","তিনি ঈশ্বর জিজ্ঞাসা করেছেন তিনি এটা কি না জানেন সে সম্পর্কে কথা বলতে। তিনি বললেন যদি আপনি তা জানতে পারেন তাহলে তিনি তা রক্ষা করবেন। তিনি বললেন তিনি আমার ভাইয়ের সাথে থাকতে পারতেন। আমি যা বলছি তা হল সে হয়তো মারা যেতে পারে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَدْرُونَ مَا الْغِيَابَةُ قَالَ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا لَيْسَ فِيهِ قَالَ أَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ لَهُ قَالَ إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏اغْتَبْتَهُ ‏ ‏وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[9523,9523,"","আমরা এমন আবেগ দূর করতে চেষ্টা করেছি, যা আমাদের রক্তের যন্ত্রণা দিয়েছে। আমি জনতার দোষ দিচ্ছি না, কিন্তু লর্ডকে আমি তোমার কাছে হারাচ্ছি, তুমি শান্ত থাকবে, এর আগে ধরা পড়বে না। আর আমি যা চাই তা করা উচিত। আমরা তর্ক করেছি, বন্য ঘোড়া থেকে তোমাকে কিনে আনতে চেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا أَنَا أَنْهَاكُمْ أَنْ تَصُومُوا يَوْمَ الْجُمُعَةِ وَلَكِنْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَصُومُوا يَوْمَ الْجُمُعَةِ إِلَّا أَنْ تَصُومُوا قَبْلَهُ وَمَا أَنَا أُصَلِّي فِي نَعْلَيْنِ وَلَكِنْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْحَارِثِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا يَسْأَلُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[9524,9524,"","আমরা এমন আবেগ দূর করতে চেষ্টা করেছি, যা আমাদের পৃথিবীর রাজার একটা খেলনার জন্য এনেছে। সে বলেছিল বাবা হারিরি আমি তার জন্য প্রার্থনা করেছি এবং সে বলল কে আমি তাকে বলেছিলাম যে, তিনি যদি তার কারারাকে দেখতে চান, তাহলে তিনি তার গাড়িতে বসে আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا الْبَرَّادَ أَبَا عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا ‏ ‏أَوْ قَالَ مَنْ صَلَّى عَلَيْهَا ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ الْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[9525,9525,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের বাবার ইচ্ছার উপর আপনার কাজ করে দিয়েছে। লর্ড তার কাছে প্রার্থনা করেছেন এবং বলেছেন তিনি তাকে আত্মসমর্পণ করবেন যে তিনি কবিতায় বিশ্বাস করেন সবকিছু.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَصْدَقَ بَيْتٍ قَالَتْهُ الشُّعَرَاءُ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏","","",""],[9526,9526,"","আমরা আমার বাবার প্রতি যে আবেগ প্রকাশ করেছি, তার কথা শুনেছি, তারপর তিনি শুনতে পান অথবা শোনেন, একটি ঘোড়া তার কাছে প্রার্থনা করে এবং সে পাপীকে এক পঞ্চম প্রার্থনা করতে দেখে। এবং তারা ভাল আছে এবং এটা মূল্য.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤَذِّنُ يُغْفَرُ لَهُ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ حَسَنَةً وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[9527,9527,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের বাবার গোপন বিষয় নিয়ে একটা দাঙ্গার সৃষ্টি করেছে। সে তার কাছে প্রার্থনা করছে এবং সে বলবে সে আগুনের উপর আলো ফেলছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَغَرَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَوَضَّئُوا مِمَّا أَنْضَجَتْ النَّارُ ‏","","",""],[9528,9528,"","আমরা বাবাকে ভালবাসি আর তাকে বলা হয়েছে যে সে আমাকে ভালোবাসে। বাবাকে সবসময় ভালোবাসে। আমি আমার বাবার জীবন দেবতা হিসেবে শুনেছি। আমি জানি, আমার ছেলের কথা। আমি জানি, আমি আমার বাবার জীবন নিয়ে একটা গান গেয়েছি। আর আমি আমার বাবার কথা শুনেছি, আমি তাকে ভালোবাসি। আমি আমার বাবার জীবন পরিবর্তন করতে। আমি জানি, আমি আমার বাবার জীবন কেমন? আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি কি, আমি তোমার বাবা। আমি আমার বাবার জীবন পরিবর্তন করতে পারি। আর আমি যদি আমার বাবার মত। আমি আমার বাবার মত মানুষ না হয়, আমি শুধু একটা ছোট্ট ছেলের সাথে কথা শুনেছি। আমি যখন প্রথম বারের মত আচরণ করি, তখন আমি আমার বাবার সাথে কথা শুনেছি। আমি যখন প্রথম বারের মত আচরণ করি, তখন আমি আমার বাবার সাথে কথা বলছি। আমি আমার বাবার সাথে আমার বাবার মত আচরণ করি, তখন আমি যখন আমি আমার বাবার সাথে কথা শুনেছি, তখন আমি আমার বাবার সাথে আমার বাবার মত আচরণ করি। আমি আমার বাবার মত আচরণ করি। অথবা অন্য যে নর্তকীর দ্বারা তাকে মনোনীত করা হয়েছে, তা ঈশ্বর কোনো সময় মনোনীত করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا فِي رَمَضَانَ مِنْ غَيْرِ رُخْصَةٍ رَخَّصَهَا اللَّهُ لَمْ يَقْضِ عَنْهُ صِيَامُ الدَّهْرِ ‏","","",""],[9529,9529,"","আমরা আমাদের আবেগ-অনুভূতি, যা আমাদের কাছে আরো সুন্দর গালের কাছাকাছি নিয়ে এসেছে, একটা ভাবটা যা ভবিষ্যদ্বাণীর কথা বলে যা আদেশ দিয়েছে আর তা ঘোষণা করা হবে যে, শেষ হয়ে যাবে একজন ভালো মানুষ জানে সে কি বলছে আর সময় হল... ...যখন আমি ছিলাম তখন থেকে দামটা মুক্ত না হয়ে যায়. আর সে ঠিক আছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَوْلًى لِقُرَيْشٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ بَيْعِ الْمَغَانِمِ حَتَّى تُقْسَمَ ‏ ‏ثُمَّ قَالَ بَعْدَ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏وَيَعْلَمُ مَا هِيَ قَالَهَا ‏ ‏يَزِيدُ ‏ ‏آخِرَ مَرَّةٍ ‏ ‏وَعَنْ بَيْعِ الثَّمَرِ حَتَّى ‏ ‏يُحْرَزَ ‏ ‏مِنْ كُلِّ ‏ ‏عَارِضٍ ‏ ‏وَأَنْ لَا يُصَلِّيَ الرَّجُلُ إِلَّا وَهُوَ ‏ ‏مُحْتَزِمٌ ‏","","",""],[9530,9530,"","ঈশ্বর আদেশ দিয়েছেন এবং তিনি তাকে আত্মসমর্পণ করবেন বলে আদেশ দিয়েছেন । অথবা জোর দিয়ে বলছি যে, আমার প্রতিবেশীকে নিয়ে যে সে ভাবে, যতক্ষণ না সে ভাবে যে সে এটা মূল্য পায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَوْصَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ يُوَرِّثُهُ ‏","","",""],[9531,9531,"","আমরা একটা নির্দিষ্ট আবেগ নিয়ে কথা বলেছি যা আমরা যখন গোপন বিষয় শুনেছি, তখন তিনি তার জন্য প্রার্থনা করেছিলেন। ঈশ্বর তাঁর জন্য প্রার্থনা করতেন এবং যদি তিনি তা না করতে চাইতেন তাহলে তিনি তার জন্য একটা অভিশাপ দিতেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ إِلَّا الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ ‏","","",""],[9532,9532,"","আর তাকে ফোন করে, আমি বাবার কথা শুনেছি, ঈশ্বরের কাছে আছে আর সে বলে যে, সব কিছু আমার জন্য। আমি ধরে আছি আর আমি এটা ধরে আছি যে বধির মুখটা আল্লাহ্‌র জন্য রান্না করছি। তোমার অনুপ্রেরণার জন্য।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَعْنِي اللَّهَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الصَّوْمُ هُوَ لِي وَأَنَا أَجْزِي بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[9533,9533,"","আমি যেসব লোকের কথা শুনেছি তারা সম্পর্কে কথা বলেছি, সে শহর দিয়ে যায়... ...সে বলে আমার বাবা একজন পলাতক... যখন তিনি তার দয়া শোনেন, এবং তাকে শান্তি প্রদান করেন এবং আত্মসমর্পণ করেন, তিনি তাকে চিন্তিত করে তাকে জিজ্ঞাসা করেন যে তিনি তাকে ক্ষমা করবেন কি না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْجُلَاسِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ شَمَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَمُرُّ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَيَمُرُّ ‏ ‏بِأَبِي هُرَيْرَةَ ‏ ‏وَهُوَ يُحَدِّثُ فَقَالَ بَعْضَ حَدِيثِكَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ثُمَّ مَضَى قَالَ ‏ ‏ثُمَّ رَجَعَ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى الْجِنَازَةِ قَالَ قَالَ ‏ ‏خَلَقْتَهَا ‏ ‏أَوْ قَالَ أَنْتَ خَلَقْتَهَا ‏ ‏شُعْبَةُ ‏ ‏الَّذِي شَكَّ ‏ ‏وَهَدَيْتَهَا إِلَى الْإِسْلَامِ وَأَنْتَ قَبَضْتَ رُوحَهَا تَعْلَمُ سِرَّهَا وَعَلَانِيَتَهَا جِئْنَا ‏ ‏شُفَعَاءَ ‏ ‏فَاغْفِرْ لَهَا ‏","","",""],[9534,9534,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা আমাদের কাছে এক অনুভূতি এনে দিয়েছে যা আমার বাবা যা শুনেছেন, তার জন্য। ঈশ্বরের কাছে প্রার্থনা করা যেন তিনি তার নাম মুছে দেন। ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং একজন উত্তম মেষপালককে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رَافِعٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ ‏ ‏كَانَ اسْمُهَا ‏ ‏بَرَّةَ ‏ ‏فَقِيلَ تُزَكِّي نَفْسَهَا ‏ ‏فَسَمَّاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ ‏","","",""],[9535,9535,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমার বাবাকে রাজকীয় বাবাকে দিতে সমস্যা করেছে। যদি আকাশ খারাপ হয়ে যায়, আমি তা খুঁজে পাব। আর বলেছে আমরা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَسْجُدُ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَقُلْتُ أَتَسْجُدُ فِيهَا فَقَالَ نَعَمْ رَأَيْتُ خَلِيلِي يَسْجُدُ فِيهَا وَلَا أَزَالُ أَسْجُدُ فِيهَا حَتَّى أَلْقَاهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[9536,9536,"","দুই দিন তিনি আমার বাবাকে দাস হিসেবে অথবা আমার ঘোড়া সম্বন্ধে কথা বলেছেন, প্রতি মাসে থেকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ يَعْنِي الْجُرَيْرِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَرَكْعَتَيْ الضُّحَى وَصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[9537,9537,"","বাবার আবেগ নিয়ে আমরা কথা বলেছি, আমরা বাবার আবেগ নিয়ে কথা বলেছি। আমার বাবা একটা উপহার যেটা আমার ঘোড়াকে ঘুমাতে যাওয়ার আগে বলা হয় আর আমার রেস্তোরা আর তিন বছর ধরে আমার রেস্তোরা ছেড়ে চলে যেতে। মাঝে মাঝে এটা যেমন ছোট থাকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي شِمْرٍ الضُّبَعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ النَّهْدِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَرَكْعَتَيْ الضُّحَى وَصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[9538,9538,"","আমরা মৃত্যু আর বেদনার প্রতি প্রবল আগ্রহ দিয়েছি, আমরা এটা নিয়ে কথা বলেছি। লর্ড প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে, কে আপনাকে ধর্মীয় প্রার্থনা থেকে উপকৃত করেছে। সূর্যটা মাটিতে চলে এসেছে, আমি তোমাকে জুস থেকে ফিরে আসতে দেব সূর্য মিস করার আগে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةِ الصُّبْحِ قَبْلَ طُلُوعِ الشَّمْسِ فَقَدْ أَدْرَكَ الصَّلَاةَ وَمَنْ أَدْرَكَ رَكْعَتَيْنِ مِنْ الْعَصْرِ قَبْلَ أَنْ تَغِيبَ الشَّمْسُ فَقَدْ أَدْرَكَ الصَّلَاةَ ‏","","",""],[9539,9539,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি, যা আমাদের বাবার দেবী হওয়ার অনুভূতি এনে দিয়েছে। ঈশ্বর তাকে আদেশ দিয়েছেন, তার কাজে তিনি বলেছেন যে তুমি শান্তি এবং শান্তি দিয়ে শুরু করবে না। তাদের আত্মার সাথে পরিচিত হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏لَا تَبْدَءُوهُمْ بِالسَّلَامِ وَإِذَا لَقِيتُمُوهُمْ فِي طَرِيقٍ فَاضْطَرُّوهُمْ إِلَى أَضْيَقِهَا ‏","","",""],[9540,9540,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা আমাদের বাবার দেবীর মতো মনে করিয়ে দিয়েছে। আল্লাহ বলেছেন, আল্লাহ যেন শপথের মতো ঈশ্বরের শপথের মধ্যে আছেন। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ مَثَلُ الْقَائِمِ لَا ‏ ‏يَفْتُرُ ‏ ‏وَمَثَلُ الصَّائِمِ لَا يُفْطِرُ حَتَّى يَرْجِعَ الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[9541,9541,"","আমার উপহারের অনুগ্রহের কথা পড়েছিঃ আপনার টাকা হলো দেবীর সুখী ছেলের ছেলে। সম্ভবত তারা তাকে বলেছিল যে আমার বাবা একজন দেবতা, যিনি উদ্ধার করতে চান। তার আনুগত্যের অন্ধকার.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏وَعَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُمَا أَخْبَرَاهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَمَّنَ ‏ ‏الْقَارِئُ فَأَمِّنُوا فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9542,9542,"","তিনি বলেছিলেন যে, আপনার টাকা সম্বন্ধে আমি বলেছিলাম এবং আমরা তাকে বলেছিলাম যে, কীভাবে বিষ দেওয়া হয়েছে । তার কাছে হস্তান্তর করা হয়েছে, তাদের কোন রক্ষিতা নেই, তারা বলে যে কে রাজি হয়েছে যে এটা কমিশনার যাকে হত্যা করা হয়নি.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9543,9543,"","তিনি বলেছিলেন, আমি আপনাকে আপনার টাকা সম্পর্কে বলেছিলাম এবং তাকে আমরা আপনাকে যা বলেছি, তা থেকে আমরা তাকে বলি। আমার পিতা সামান, আমার বাবা একজন দেবতা, কারণ আমার বাবা এটা করতে বলেছেন এবং তাকে তা করতে বলা হয়েছে। আপনার হৃদয় থেকে প্রভু আপনার সঙ্গে বিশ্বাসঘাতকতা করেছেন বলে আপনার হৃদয় থেকে তিনি আপনাকে রক্ষা করবেন ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9544,9544,"","তিনি আমাকে ক্ষমার অযোগ্যতা সম্পর্কে বলেছেন: আমার মুখের সামনে আপনার টাকা। ঈশ্বরের আছে যদি আমি বিশ্বাস করি যে আপনি আকাশের শপথ নিয়ে চলে গেছেন।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ أَحَدُكُمْ آمِينَ قَالَتْ الْمَلَائِكَةُ فِي السَّمَاءِ آمِينَ فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9545,9545,"","সে বলেছিল, আমরা তোমার টাকা নিয়ে কথা বলেছি যখন সে লাঠি পেতে চেষ্টা করছিল। আমার বাবার ছেলে শুনেছি সে নাকি তার প্রার্থনা শুনেছে। থান্ডারের প্রার্থনা আমি লর্ডকে পৌছে দেব, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার কাছে প্রার্থনা করেছেন, এটা বলা হয়নি যে আপনি এমন একজন ব্যক্তি যিনি এটা করতে পারতেন। সে মানুষের কাছে হস্তান্তর করেছে যারা বলেছে হাত ধরে বলতে যে আমরা ঈশ্বরের কাছে প্রার্থনা করছি। তারপর আরো কয়েকটা নতুন লোক আছে এবং এটা একটা গ্যালাক্সি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏ابْنِ أَبِي أَحْمَدَ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعَصْرِ فَسَلَّمَ مِنْ ‏ ‏رَكْعَتَيْنِ فَقَامَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالَ أَقَصُرَتْ الصَّلَاةُ يَا رَسُولَ اللَّهِ أَمْ نَسِيتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ ذَلِكَ لَمْ يَكُنْ فَقَالَ قَدْ كَانَ ذَلِكَ يَا رَسُولَ اللَّهِ فَأَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى النَّاسِ فَقَالَ أَصَدَقَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالُوا نَعَمْ ‏ ‏فَأَتَمَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَقِيَ مِنْ صَلَاتِهِ ثُمَّ سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[9546,9546,"","তিনি বলেছিলেন, তিনি কি বলেছেন তা বলার চেষ্টা করেছি। আমার বাবা আমার বাবা হলেন ঈশ্বরের লর্ডের জিনিয়াস। তিনি যখন একটা চাকরি খুঁজে পেয়েছিলেন, তখন তিনি তৃতীয় ঘন্টার মধ্যে একটা পথ খুঁজে পেয়েছিলেন । যখন সকালে সাঁতার কাটতে হয়েছিল, তখন সে গত কয়েক ঘন্টা ধরে চলে গিয়েছিল ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏غُسْلَ ‏ ‏الْجَنَابَةِ ‏ ‏ثُمَّ رَاحَ فَكَأَنَّمَا قَرَّبَ ‏ ‏بَدَنَةً ‏ ‏وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ فَكَأَنَّمَا قَرَّبَ بَقَرَةً وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ فَكَأَنَّمَا قَرَّبَ كَبْشًا ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏أَقْرَنَ ‏ ‏وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ فَكَأَنَّمَا قَرَّبَ دَجَاجَةً وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ فَكَأَنَّمَا قَرَّبَ بَيْضَةً فَإِذَا خَرَجَ الْإِمَامُ أَقْبَلَتْ الْمَلَائِكَةُ يَسْتَمِعُونَ الذِّكْرَ ‏","","",""],[9547,9547,"","আমরা আমার ভাই হাররাহের প্রতি আমার ভালবাসা নিয়ে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করবেন, মনে হয় সে কোন পাগল হয়ে যাবে না, সে মনে করে বেঁচে যাবে, সে ফিরে আসবে। সে আর কখনোই তার সাথে জনগণের নিকট ফিরে আসবে না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبَايَعُوا بِالْحَصَاةِ وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا تَبَايَعُوا بِالْمُلَامَسَةِ وَمَنْ اشْتَرَى مِنْكُمْ ‏ ‏مُحَفَّلَةً ‏ ‏فَكَرِهَهَا فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ ‏","","",""],[9548,9548,"","তিনি বললেন, আমি ক্ষমার পর্দার উপর পড়েছি: আপনার সন্তানের জন্য আপনার টাকা ঈশ্বরের দয়ায় ক্ষমার উপর একটি শহীদ সন্তানের জন্য। ঈশ্বরের দোহাই, আল্লাহ তা উদ্ধার করতে হবে এবং আমি যদি বলি যে, ঈশ্বর আমাকে ক্ষমা করে দিতে চান, তাহলে আপনার অর্থ হবে। আমার মা'কে নিয়ে চিন্তা করতে চাইনা,","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ وُضُوءٍ ‏","","",""],[9549,9549,"","সে বলেছিল আমরা তোমাকে তোমার ভালবাসার কথা বলতে চাই, আমি আমার বাবার জন্য বাহিরে যাচ্ছি, যে ঈশ্বরকে জিজ্ঞেস করবে তার সাত বার।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏","","",""],[9550,9550,"","সে বলেছে, আমি তোমার টাকার আশীর্বাদ পেয়েছি আর আমরা কথা বলেছি তুমি কিভাবে এটা করেছ, তার বাবার কাছে এটা নিশ্চিত করার জন্য তাকে শাস্তি দেয়া হয়েছে। প্রার্থনা করে তাকে শ্রদ্ধা জানানো হবে, যদি সে প্রার্থনা করে, সে হারিয়ে যাবে এবং কথা শুনবে। তারা প্রার্থনা করবে যখন আপনি প্রার্থনায় আপনার কাছে থাকবেন, যদি তিনি প্রস্তুত না থাকেন। প্রার্থনা করো।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏وَإِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ فَلَا تَأْتُوهَا وَأَنْتُمْ ‏ ‏تَسْعَوْنَ ‏ ‏وَأْتُوهَا وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا فَإِنَّ أَحَدَكُمْ فِي صَلَاةٍ إِذَا مَا كَانَ ‏ ‏يَعْمِدُ ‏ ‏الصَّلَاةَ ‏","","",""],[9551,9551,"","সে আমাকে বলেছে আমার ছেলে, আমার বাবার ব্যাপারে, আমার ভাই, তার ঈশ্বর সম্পর্কে আমি তোমার সব থেকে ভালো কিছু পড়েছি। ঈশ্বর বলতে চান আমরা যদি শয়তানের সেরা অনুশীলনে যেতে চাই, যদি সে শোনা না যায়, তবুও সুলতানকে এমনকি বিজয় শুনতে না পাওয়া পর্যন্ত মারধর করা হয়েছে। আর বলে যে আমি মনে করি, তাই আমি ভাবছি, তাই কেন নয় যখন একজন মানুষ মানুষ হিসেবে কাজ করে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ ‏ ‏أَدْبَرَ ‏ ‏الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ فَإِذَا قُضِيَ النِّدَاءُ أَقْبَلَ حَتَّى إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ ‏ ‏أَدْبَرَ ‏ ‏الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ حَتَّى إِذَا ‏ ‏قُضِيَ ‏ ‏التَّثْوِيبُ ‏ ‏أَقْبَلَ ‏ ‏يَخْطِرُ ‏ ‏بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ حَتَّى ‏ ‏يَظَلَّ ‏ ‏الرَّجُلُ إِنْ يَدْرِي كَمْ صَلَّى ‏","","",""],[9552,9552,"","আমি তোমার টাকার উপর পড়েছি আর আমরা তোমাকে বলবো, সে বলেছে বাবা তাকে দয়া করে বলতে বলেছে, সে তোমার প্রার্থনা মানায় নাই আমি মাঝে মাঝে এম. ভি পড়তে হারাতাম আর ঈশ্বর আমার সাথে এমন আচরণ করেছেন যে ঈশ্বর আমার ছেলে আর আমার জন্য এটা অর্জন করেছেন। ঈশ্বর তাকে আদেশ দিয়েছেন এবং বলবেন যে ঈশ্বর হয়ত বলবেন, আমার হৃদয় যেন প্রিয় হয়, ঈশ্বরের দয়ায় গান বাজানো। ঋণ হলো আল্লাহ্ খুশি এবং সকল মঙ্গলভাবের কথা বলেন। কিন্তু আমাকে খেলতে হবে। আমি যা বলবো, আমাদের কাছে ভুলের নিয়ন্ত্রণ আছে, আমি অতিথি নই।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى ‏ ‏هِشَامِ بْنِ زُهْرَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏هِيَ ‏ ‏خِدَاجٌ ‏ ‏هِيَ ‏ ‏خِدَاجٌ ‏ ‏غَيْرُ تَمَامٍ فَقُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏إِنِّي أَحْيَانًا أَكُونُ وَرَاءَ الْإِمَامِ قَالَ ‏ ‏فَغَمَزَ ‏ ‏ذِرَاعِي وَقَالَ اقْرَأْ بِهَا يَا فَارِسِيُّ فِي نَفْسِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ فَنِصْفُهَا لِي وَنِصْفُهَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَءُوا يَقُولُ الْعَبْدُ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ حَمِدَنِي عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏الرَّحْمَنِ الرَّحِيمِ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ أَثْنَى عَلَيَّ عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏مَالِكِ يَوْمِ الدِّينِ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ مَجَّدَنِي عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ هَذِهِ الْآيَةُ بَيْنِي وَبَيْنَ عَبْدِي وَلِعَبْدِي مَا سَأَلَ يَقُولُ الْعَبْدُ ‏ { ‏اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَهَؤُلَاءِ لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ ‏","","",""],[9553,9553,"","আমরা আমাদের সবচেয়ে ভালো জিনিস নিয়ে কথা বলেছি, বাবা যে জাদু শুনে আমার বাবার কাছে বড় হয়েছে, সে একজন পলাতককে ঈশ্বরের কাছে পাঠানো হয়েছে, যাকে বলা হয়েছিল তাকে বলা হয়েছে যে তুমি আমার হতে চাও না মেয়ে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِنْ ‏ ‏النَّخْعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[9554,9554,"","তিনি কল্পনার ফর্মগুলোকে ঘৃণা করতেন, এই কথা বলে যে, তাঁর একজন পুরুষ সাদা বা সাদা হয়ে যাবে ।","‏ ‏وَكَانَ ‏ ‏يَكْرَهُ ‏ ‏الشِّكَالَ ‏ ‏مِنْ الْخَيْلِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَعْنِي إِحْدَى رِجْلَيْهِ سَوَادٌ أَوْ بَيَاضٌ ‏","","",""],[9555,9555,"","বাবা আমাকে বলেছিলেন যে, আমি যদি খুশি হতে চাই, তাহলে সে আমাকে যেতেই দেবে। সে বলল, আমি তার জন্য প্রার্থনা করেছি এবং সে বলছে আমি কি ক্ষমা প্রার্থনা করছি। আগুন থেকে বেরিয়ে আসা","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ أَبِي سَعِيدٍ الْمَقْبُرِيَّ ‏ ‏بَعْدَمَا كَبِرَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَسْفَلُ مِنْ الْكَعْبَيْنِ مِنْ ‏ ‏الْإِزَارِ ‏ ‏فِي النَّارِ ‏","","",""],[9556,9556,"","আমরা বাবার দয়া নিয়ে কথা বলেছি তারপর আমরা শুনেছি, আল্লাহ তার কাছে প্রার্থনা করেছেন, তিনি বলেছেন তার কাছে আছে এবং তিনি সকল প্রকার ক্ষতি মাফ করবেন। তিনি লিখেছেন তার কাছে পঞ্চম ও দশ জন আছে এবং তিনি সক্ষম সে তাদের সাথে কি করবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا يَحْيَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُغْفَرُ لِلْمُؤَذِّنِ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[9557,9557,"","আমরা আমাদের বাবার সবচেয়ে ভালো কথা বলেছি, ঈশ্বরের ইচ্ছা হবে তার কাছে প্রার্থনা করা, আর প্রার্থনা করলে সে ঈর্ষান্বিত হবে না, যা আত্মসমর্পণ করবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏إِغْرَارَ فِي صَلَاةٍ وَلَا تَسْلِيمٍ ‏","","",""],[9558,9558,"","আমরা রাজধানীর সেরা দুই বছরের কথা বলেছি আমার বাবার ভালো বিশ্বাসের জন্য, এমন এক মেয়ে খুঁজে পাওয়া যে এই কাজে দক্ষ। আমি সামনে এগিয়ে যাচ্ছি এবং বলতে চাই, ঈশ্বর কখনো যেন না যান। একটা চুমু ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي رَهْمٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِنْ الْمَسْجِدِ فَرَأَى امْرَأَةً تَنْضَخُ طِيبًا لِذَيْلِهَا إِعْصَارٌ قَالَ يَا أَمَةَ الْجَبَّارِ مِنْ الْمَسْجِدِ جِئْتِ قَالَتْ نَعَمْ قَالَ وَلَهُ تَطَيَّبْتِ قَالَتْ نَعَمْ قَالَ فَارْجِعِي فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَا يَقْبَلُ اللَّهُ لِامْرَأَةٍ صَلَاةً تَطَيَّبَتْ لِلْمَسْجِدِ ‏ ‏أَوْ لِهَذَا الْمَسْجِدِ ‏ ‏حَتَّى تَغْتَسِلَ غُسْلَهَا مِنْ الْجَنَابَةِ ‏","","",""],[9559,9559,"","জীবনের সবচেয়ে সেরা দু'জন জীবন নিয়ে আমি কথা বলেছি, ঈশ্বরের নাম নষ্ট হয়ে যাচ্ছে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَجَدْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏وَاقْرَأْ بِاسْمِ رَبِّكَ ‏","","",""],[9560,9560,"","আমরা বললাম, আমার বাবাকে বলতে, সে কি বলবে, সেই হবে সেই হবে সেই হবে। সে-ই হবে সেই লোক যে হবে সেই ব্যক্তি যে হবে হবে সেই হবে একজন যে হবে সেই হবে । ঈশ্বর প্রার্থনা করতে নিজেকে উৎসর্গ করেননি বলে তিনি বলেন যে তিনি আর নেই। প্রার্থনায় ঈর্ষান্বিত হয়ে আমি হয়তো তার কাছ থেকে এটা ছেড়ে দিয়েছিলাম যতক্ষণ না তা শেষ হয়ে যায় ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَأَلْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏عَنْ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏إِغْرَارَ فِي الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا هُوَ لَا غِرَارَ فِي الصَّلَاةِ وَمَعْنَى غِرَارٍ يَقُولُ لَا يَخْرُجُ مِنْهَا وَهُوَ يَظُنُّ أَنَّهُ قَدْ بَقِيَ عَلَيْهِ مِنْهَا شَيْءٌ حَتَّى يَكُونَ عَلَى الْيَقِينِ وَالْكَمَالِ ‏","","",""],[9561,9561,"","আমরা সবচেয়ে ভালো কথা বলেছি, লর্ডের আনন্দের কথা শুনে... ... প্রভুর অনুগ্রহের আদেশ এসেছে সিংহাসনের সিংহাসনের সিংহাসনে তার সিংহাসনে বসবেন... এপার্টমেন্ট.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏مَنْصُورٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّادِقَ الْمَصْدُوقَ ‏ ‏صَاحِبَ هَذِهِ الْحُجْرَةِ يَقُولُ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏","","",""],[9562,9562,"","আমরা বাবার সবচেয়ে ভালো কথা বলেছি, দুই বছর আগে, বাবার মৃত্যুর ব্যাপারে আমার বাবার নাম নিয়ে। পাগল হয়ে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجُّ ‏ ‏الْمَبْرُورُ ‏ ‏لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ وَالْعُمْرَتَانِ ‏ ‏تُكَفِّرَانِ ‏ ‏مَا بَيْنَهُمَا مِنْ الذُّنُوبِ ‏","","",""],[9563,9563,"","ঈশ্বর শপথের অর্থ ও ক্ষমার জন্য বরকে উৎসর্গ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[9564,9564,"","আমার ছেলেকে মুক্ত করার বিষয়ে আমাদের সময়ের সবচেয়ে ভাল কথা আমরা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ جُهِلَ عَلَيْهِ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[9565,9565,"","আমরা বাবার জীবন নষ্ট করার ব্যাপারে কথা বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর মানুষকে না বলার জন্য ঈশ্বরকে ধন্যবাদও দেয়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الرَّبِيعُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ ‏","","",""],[9566,9566,"","আমরা বাবার ভাগ্য নিয়ে কথা বলেছিলাম যখন তিনি তার কথা নিয়ে ঈর্ষান্বিত ছিলেন, তখন তিনি বলেছিলেন, একটি ঘোড়া তার কাছে প্রার্থনা করেছে এবং বলেছেন বধির লর্ড তার কাছে প্রার্থনা করেছে। আমি হলাম আমার বাবার ভাগ্য। আমি বলছি, আমার বাবার ভাগ্যের কথা, সে সবসময় আমার বাবার কাছে প্রার্থনা করে। আমি জানি, আমার বাবা সবসময় আমার কাছে এমনটি ছিল না। আমি জানি, আমি কি, আমার বাবা আমাকে জিজ্ঞেস করছে, বিষয়বস্তু স্টাইল- স্টাইল-শিট শৈলী শিরোনামের বারের ধরন শিরোনাম-ট gst-এরঙঙঙীয়","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏مَوْلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَنَحْنُ فِي ‏ ‏مَسْجِدِ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَاحِبُ هَذِهِ الْحُجْرَةِ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏","","",""],[9567,9567,"","আমি বলেছিলাম যে আমার জীবনে সবচেয়ে ভালো বিষয়টা হচ্ছে ঈশ্বর আমাকে বধির লোকেদের কাছে পৌঁছে দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[9568,9568,"","আমরা কথা বলেছিলাম আমার বাবা ছেলেটির ব্যাপারে কতটা ভালো ছিলেন, ঈশ্বর তাকে জিজ্ঞেস করেছেন। তিনি আমাকে জীবিত থাকতে বলেছেন। আমরা আমার বাবাকে আনন্দের সাথে খুঁজে পাব যে তার কাছে প্রার্থনা করেছে। এটা একটা অপরাধ, আর যদি আমি তোমাকে খুঁজে পাই, এটা বোঝা সহজ হবে না। নাবিক বলেছে, আমি একজন বিজয়ী আর তিনি বলেছেন, \"আমি একজন খুনি।\"","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏وَإِذَا كَانَ أَحَدُكُمْ يَوْمًا صَائِمًا فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ أَحَدٌ شَتَمَهُ ‏ ‏أَوْ فَإِنْ امْرُؤٌ شَتَمَهُ ‏ ‏فَلْيَقُلْ إِنِّي صَائِمٌ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَإِنْ امْرُؤٌ شَتَمَهُ أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي صَائِمٌ ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوْ قَاتَلَهُ ‏","","",""],[9569,9569,"","আমার বাবার প্রেমের জন্য আমার বাবার নাম নিয়ে আমার নাম নিয়ে আমি আপনার সবচেয়ে ভাল টাকা নিয়ে কথা বলেছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَةُ ‏ ‏تُكَفِّرُ ‏ ‏مَا بَيْنَهَا وَبَيْنَ الْعُمْرَةِ وَالْحَجُّ ‏ ‏الْمَبْرُورُ ‏ ‏لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ ‏","","",""],[9570,9570,"","বাবা হারাহর কথা বলেছিলাম যে তিনি ঈশ্বরের কথা শুনেছেন যে তিনি গর্ভাবস্থার কথা বলেছেন, তার কাছে একটা গুরুতর অপরাধ আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏","","",""],[9571,9571,"","ঈশ্বর আমাদের কাছে যে - বিষয়টা তুলে ধরেছেন, তা হল, সেই শহরে একটা গাছ উদ্ধার করা, একটা গাছের ছায়াতে থাকা যাত্রীকে তার ছায়াতে নিয়ে যাবে, যার ১০০ বছরের ছায়াবিহীন ছায়াতে অপরাধ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الضَّحَّاكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا شَجَرَةَ الْخُلْدِ ‏","","",""],[9572,9572,"","তিনি আমাকে ক্ষমার জন্য অনুসন্ধান করতে বলেছেন: আমার দেবীর প্রতি ভালোবাসার জন্য আপনার টাকা প্রার্থনা করুন, তিনি তার ভাইয়ের পাপের জন্য আপনাকে ভুল করেননি বলে তাকে ধন্যবাদ দিয়েছেন.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَخْطُبُ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ ‏","","",""],[9573,9573,"","সে বলেছে আমার ছেলে, আমার বাবার ব্যাপারে, আমার ভাই, তার ঈশ্বর সম্পর্কে আমি তোমার সব থেকে ভালো টাকা পড়েছি। তাকে অভিশাপ দিয়েছে আর দেখা যাবে না।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلَا بَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[9574,9574,"","তিনি বলেছিলেন: “আপনার টাকা আমাকে রক্ষা করার জন্য আপনার টাকা স্থানান্তর করা হয়েছে । এটা তার কাছে পেশ করুন, তিনি সকাল পর্যন্ত প্রার্থনা করতে চেয়েছিলেন আপনি সূর্য উদিত হতে না হওয়া পর্যন্ত","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَعَنْ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[9575,9575,"","সে বলেছে, আমি তোমার টাকা নিয়ে তোমার টাকা নিয়ে কথা বলেছি... ...কীভাবে আমার নিজের জীবনে ফিরে যেতে হবে, তার বদলে খুব খুশির ব্যাপার হবে। আমি চাঁদ থেকে সরে যেতে চাই... ...তুমি সূর্যকে উড়িয়ে দেওয়ার আগেই.","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏وَعَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏وَعَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ وَمَنْ أَدْرَكَ رَكْعَةً مِنْ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ ‏","","",""],[9576,9576,"","আমি তোমাদের কাছে ঈশ্বরের আশার চেয়ে তোমাদের টাকা পড়েছি, কিন্তু লর্ডের কাছে আমার বাবার দয়া আছে, তিনি বলেছেন যে ঈশ্বর চলে গেছেন। এই প্রার্থনা করে স্ট্যাচুর আবার ফিরে এসেছে। আগুন থেকে আগুন নিভে যেত আর মনে করতে হতো যে আগুন যেন দেবতা ছিল।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْأَسْوَدِ بْنِ سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَمُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ وَذَكَرَ أَنَّ النَّارَ اشْتَكَتْ إِلَى رَبِّهَا فَأَذِنَ لَهَا فِي كُلِّ عَامٍ بِنَفَسَيْنِ نَفَسٍ فِي الشِّتَاءِ وَنَفَسٍ فِي الصَّيْفِ ‏","","",""],[9577,9577,"","সে বলেছে, আমি তোমার সবচেয়ে ভালো টাকার ব্যাপারে পড়েছি আর তোমার টাকা নিয়ে কথা বলেছি, যাতে তুমি কি করছো তা জানার চেষ্টা করতে পারো। আমার বাবা তার কাছে প্রার্থনা করে বলল। ( মথি ৫: ৩, ৪) তিনি কথা বলার ক্ষেত্রে স্বাধীন হবেন ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[9578,9578,"","বাবার ভাগ্যের কথা বলেছিলাম আমার বাবার নগ্ন হওয়া নিয়ে কথা বলার জন্য। ঈশ্বর বলবে কে স্বর্গে যাবে আর ঘুমাতে যাবে না। না, সে মাসে কখনো চুমু খেতে পারেনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يَدْخُلُ الْجَنَّةَ يَنْعَمُ وَلَا يَبْأَسُ لَا ‏ ‏تَبْلَى ‏ ‏ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ إِنَّ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[9579,9579,"","আমাদের বাবা - মায়ের সবচেয়ে ভালটা সম্বন্ধে আমরা বলেছিলাম । গ্রাম, আর তাই সে বলেছিল যে, তাকে তোমাকে ভালোবাসতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى فَأَرْصَدَ اللَّهُ عَلَى مَدْرَجَتِهِ مَلَكًا فَقَالَ لَهُ أَيْنَ تَذْهَبُ قَالَ أَزُورُ أَخًا لِي فِي اللَّهِ فِي قَرْيَةِ كَذَا وَكَذَا قَالَ هَلْ لَهُ عَلَيْكَ مِنْ نِعْمَةٍ تَرُبُّهَا قَالَ لَا وَلَكِنَّنِي أَحْبَبْتُهُ فِي اللَّهِ عَزَّ وَجَلَّ قَالَ فَإِنِّي رَسُولُ اللَّهِ إِلَيْكَ ‏ ‏أَنَّ اللَّهَ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ فِيهِ ‏","","",""],[9580,9580,"","আমার ভালোবাসার জন্য আমার দেবতাদের ব্যাপারে আমি সব থেকে ভালো কথা বলেছি, আমার বাবা আমার বাবার ব্যাপারে ঝামেলা করছে, আমার বাবা তার শান্তির জন্য প্রার্থনা করেছে, প্রভু সে বিষের মত বিষ চাইবে ওর ভাই না হলে সে নিজের রাস্তা ঠিক করে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَسْتَامَ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ أَوْ يَخْطُبَ عَلَى خِطْبَتِهِ ‏","","",""],[9581,9581,"","আমরা বাবার ভালোবাসার ব্যাপারে এত নিষ্ঠুর হওয়ার কথা বলেছিলাম, যে অন্ধের মত একটা মেয়েকে কিনেছিল, যে সন্তুষ্ট হবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَلْيَحْلِبْهَا فَإِنْ لَمْ يَرْضَهَا فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[9582,9582,"","আমরা আমার ভাই-বোনের জন্য আপনার সবচেয়ে ভালো টাকা নিয়ে কথা বলেছি, ঈশ্বর বলতে চাচ্ছেন কে যেন তার শোকের সময় একটা দাগ ফেলে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَأَلَهُ جَارُهُ أَنْ ‏ ‏يَغْرِزَ ‏ ‏خَشَبَةً فِي جِدَارِهِ فَلَا يَمْنَعْهُ ‏","","",""],[9583,9583,"","মাহদির সবচেয়ে ভালোটা নিয়ে আমরা কথা বলেছি। আমি তার ব্যাপারে কথা বলেছি। আমি বরং আমার বাবা একজন সাহসী ছিলেন যে ঈশ্বরের কাছে প্রার্থনা করতো যদি সে আপনার একজনকে হত্যা করে। তার এই ভাষণের মাধ্যমে তিনি তার ভাবমূর্তি রক্ষা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هُمَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ ‏ ‏قَالَ ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ ‏ ‏آدَمَ ‏ ‏عَلَى صُورَتِهِ ‏","","",""],[9584,9584,"","আমরা আমার বাবা ভগবানের উপর ভরতি হওয়ার ব্যাপারে কথা বলেছি, সে বলল যদি সে এই টর থেকে কিছু চায় না আর যখন সে রাস্তা থেকে বের হয় তখন তা দেখেনা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَنْذِرُوا ‏ ‏فَإِنَّ ‏ ‏النَّذْرَ ‏ ‏لَا يَرُدُّ شَيْئًا مِنْ الْقَدَرِ وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[9585,9585,"","আমি আমার ভাইয়ের সবচেয়ে ভাল কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ عَبْدِي وَأَمَتِي كُلُّكُمْ عَبِيدُ اللَّهِ وَكُلُّ نِسَائِكُمْ إِمَاءُ اللَّهِ وَلَكِنْ لِيَقُلْ غُلَامِي وَجَارِيَتِي وَفَتَايَ وَفَتَاتِي ‏","","",""],[9586,9586,"","আমরা আমার বাবা ঈশ্বরের দোহাইর সাথে কথা বলেছিলাম, সে বলত, ছেলেটির কাছে যাওয়ার জন্য ঈশ্বরের ইচ্ছার মধ্যে কি হতে পারে, মূল্যবোধ এবং ৩ জনের পাগলামিতে প্রবেশ করা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا قَعَدَ قَوْمٌ مَقْعَدًا لَا يَذْكُرُونَ اللَّهَ عَزَّ وَجَلَّ وَيُصَلُّونَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا كَانَ عَلَيْهِمْ حَسْرَةً يَوْمَ الْقِيَامَةِ وَإِنْ دَخَلُوا الْجَنَّةَ ‏ ‏لِلثَّوَابِ ‏","","",""],[9587,9587,"","আমি বাবার সম্পর্কে আমাদের সবচেয়ে ভালো কথা বলেছি, ঈশ্বর তাকে বলেছেন যে আমাকে ঘুমের মধ্যে দেখেছে, সে আমাকে দেখেও আমাকে দেখে নি","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ بِمِثْلِي ‏","","",""],[9588,9588,"","আমরা আমার ছেলের জন্য দুই ঘোড়া হয়ে যাওয়ার ব্যাপারে কথা বলেছিলাম, সে ছেড়ে দেবে যে কিনা ঈশ্বর দ্বারা চালিত ছিল এবং অন্য জন তার অতিথিকে হারিয়ে ফেলবে এবং সে ছিল তার বিশ্বাস করা। আল্লাহ আর অন্যকারো জন্য ভালো বলতে বা না যেতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ ‏","","",""],[9589,9589,"","আমরা আমার শ্বশুর আব্বার সাথে সম্পর্ক নিয়ে দুই গ্রীষ্মের কথা বলেছি। আমি বলবো না, আমি তোমাকে ক্ষমা করবো কিন্তু ঈশ্বরের দোহাই আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ اللَّهُمَّ ارْحَمْنِي إِنْ شِئْتَ وَلَكِنْ ‏ ‏لِيَعْزِمْ ‏ ‏الْمَسْأَلَةَ فَإِنَّهُ لَا مُكْرِهَ لَهُ ‏","","",""],[9590,9590,"","আমরা আমার শ্বশুর আব্বাকে নিয়ে দুই গ্রীষ্মের কথা বলেছি। সে আত্মসমর্পণ করেছে যে পানিকে পাথর দিয়ে পাথর মেরে ফেলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[9591,9591,"","আমরা দুই গ্রীষ্মের কথা বলেছি আমার শ্বশুর আব্বাকে নিয়ে যেতে হলে তাকে অবশ্যই আত্মসমর্পণ করতে হবে, যে কিনা ঈশ্বর ও অন্য আরেকজনের প্রেমে পড়ে যেত। অতিথি, যার নিজের ভাগ্যের দ্বারা প্রভাবিত হতো, সে চুপ করে থাকে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ ‏","","",""],[9592,9592,"","আমরা আমার ভাইকে আমার ছেলের ব্যাপারে একটা উৎকণ্ঠা হিসেবে নিয়ে কথা বলেছি, ঈশ্বর পানিকে পুরোপুরি প্রতিরোধ করেননি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مَنْعِ ‏ ‏فَضْلِ ‏ ‏الْمَاءِ لِيُمْنَعَ بِهِ ‏ ‏الْكَلَأُ ‏","","",""],[9593,9593,"","আর তাকে ফোন করে তিনি বলেছিলেন, ঈশ্বরের কাছে প্রার্থনা করেছেন, আর আমরা প্রভুর সাথে থাকতে পারব, আর আমার মেয়েদের এপার্টমেন্ট হল আমার বন্ধু।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا ‏ ‏مَعْشَرَ ‏ ‏الْأَنْبِيَاءِ ‏ ‏لَا نُورَثُ مَا تَرَكْتُ بَعْدَ ‏ ‏مَئُونَةِ ‏ ‏عَامِلِي وَنَفَقَةِ نِسَائِي ‏ ‏صَدَقَةٌ ‏","","",""],[9594,9594,"","( গীতসংহিতা ৩৪: ৮) আর তাকে বলার দ্বারা তিনি ঈশ্বরকে বলেছিলেন যে, তাঁকে সিদ্ধ গান গাওয়া থেকে উদ্ধার করতে পারবে ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ وَمَنْ ‏ ‏أُحِيلَ ‏ ‏عَلَى مَلِيءٍ ‏ ‏فَلْيَحْتَلْ ‏","","",""],[9595,9595,"","আমার পুত্ত্র ও পুত্ত্র নিদ্রা যায় না ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ‏ ‏الْأَنْبِيَاءُ إِخْوَةٌ أَوْلَادُ ‏ ‏عَلَّاتٍ ‏ ‏وَلَيْسَ بَيْنِي وَبَيْنَ ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏نَبِيٌّ ‏","","",""],[9596,9596,"","আমরা একটি সুখী পুত্র দ্বারা চালিত হয়েছি এবং তিনি ঈশ্বরের প্রতি ভালোবাসার প্রভু। আমি আমার প্রিয় বাবার জন্য বাইরে যাচ্ছি। তিনি বললেন, ঈশ্বর তাকে বাড়ি নির্মাণ করতে বলছেন নাকি না যেতে। আমার ছেলে না, কাজের বাইরে কাজ করা আমার ছেলে না।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرَ بْنُ سَعْدٍ وَهُوَ أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ يَعْنِي الْأَعْرَجَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ‏ ‏الْأَنْبِيَاءُ أَبْنَاءُ ‏ ‏عَلَّاتٍ ‏ ‏وَلَيْسَ بَيْنِي وَبَيْنَ ‏ ‏عِيسَى ‏ ‏نَبِيٌّ ‏","","",""],[9597,9597,"","আমরা আমার ছেলের শ্বশুরের বিরুদ্ধে আরেকজনের তলোয়ার কথা বলেছি, তাকে আত্মসমর্পণ করতে হবে, সে লোকদের কাছে ঈশ্বরকে উৎসর্গ করবে, সে তাদের হত্যা করবে, সে যুদ্ধের জন্য সে যা করতে ব্যর্থ হবে। ( আদিপুস্তক ৩: ১ - ৫) এরপর ঈশ্বর তার খুনিদের হত্যা করার জন্য হত্যা করবেন যতক্ষণ না তিনি বিচার করেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَضْحَكُ اللَّهُ إِلَى رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا الْآخَرَ كِلَاهُمَا يَدْخُلُ الْجَنَّةَ يُقَاتِلُ هَذَا فِي سَبِيلِ اللَّهِ فَيُسْتَشْهَدُ قَالَ ثُمَّ يَتُوبُ اللَّهُ عَلَى قَاتِلِهِ فَيُسْلِمُ فَيُقَاتِلُ فِي سَبِيلِ اللَّهِ حَتَّى يُسْتَشْهَدَ ‏","","",""],[9598,9598,"","( গীত.","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَمُّوا الْعِنَبَ الْكَرْمَ فَإِنَّمَا الْكَرْمُ الرَّجُلُ الْمُسْلِمُ ‏","","",""],[9599,9599,"","আমরা আমার ছেলের ব্যাপারে ২ জন ছেলের ভালো কথা বলেছি, সে বলেছিল যে জাদুবিদ্যার শপথ আর অপরাধীদের পিছু নিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَطْلُ ‏ ‏ظُلْمُ الْغَنِيِّ وَمَنْ ‏ ‏أُتْبِعَ ‏ ‏عَلَى مَلِيءٍ ‏ ‏فَلْيَتْبَعْ ‏","","",""],[9600,9600,"","আর সে তাকে ফোন করবে যে তার জন্য প্রার্থনা করেছিল আর সে আমাকে কিছু বলবে না, আমার মনে হয় সে এটা জানতে চাইবে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا مُسْتَكْرِهَ لَهُ وَلَكِنْ ‏ ‏لِيَعْزِمْ ‏ ‏فِي الْمَسْأَلَةِ ‏","","",""]];
